mutationPlans.source:
//! Bounded per-stream output capture shared by native sandbox backends.

#[cfg(any(target_os = "linux", test))]
use std::time::Duration;
use tokio::io::{AsyncRead, AsyncReadExt};

pub const MAX_OUTPUT_BYTES: usize = 1_000_000;
const TRUNCATION_MARKER: &str = "\n... (truncated)";

/// Keeps captured bytes outside the drain future so cancellation preserves them.
pub(crate) struct CappedOutput<R> {
    reader: R,
    kept: Vec<u8>,
    truncated: bool,
    finished: bool,
}

impl<R> CappedOutput<R>
where
    R: AsyncRead + Unpin,
{
    pub(crate) fn new(reader: R) -> Self {
        Self {
            reader,
            kept: Vec::with_capacity(8192),
            truncated: false,
            finished: false,
        }
    }

    pub(crate) async fn drain(&mut self) {
        let mut buffer = [0_u8; 8192];
        while !self.finished {
            match self.reader.read(&mut buffer).await {
                Ok(0) => self.finished = true,
                Ok(read) => {
                    let remaining = MAX_OUTPUT_BYTES.saturating_sub(self.kept.len());
                    let take = remaining.min(read);
                    self.kept.extend_from_slice(&buffer[..take]);
                    self.truncated |= take < read;
                }
                Err(_) => self.finished = true,
            }
        }
    }

    #[cfg(any(target_os = "linux", test))]
    pub(crate) async fn drain_for(&mut self, duration: Duration) {
        let _ = tokio::time::timeout(duration, self.drain()).await;
    }

    pub(crate) fn finish(self) -> (String, bool) {
        let text = String::from_utf8_lossy(&self.kept).into_owned();
        truncate_utf8(text, MAX_OUTPUT_BYTES, self.truncated || !self.finished)
    }
}

pub async fn read_capped<R>(reader: R) -> (String, bool)
where
    R: AsyncRead + Unpin,
{
    let mut output = CappedOutput::new(reader);
    output.drain().await;
    output.finish()
}

pub fn truncate_utf8(text: String, cap: usize, already_truncated: bool) -> (String, bool) {
    if !already_truncated && text.len() <= cap {
        return (text, false);
    }
    let content_cap = cap.saturating_sub(TRUNCATION_MARKER.len());
    let mut end = content_cap.min(text.len());
    while end > 0 && !text.is_char_boundary(end) {
        end -= 1;
    }
    let mut output = text[..end].to_string();
    output.push_str(TRUNCATION_MARKER);
    (output, true)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::io::AsyncWriteExt;

    #[test]
    fn truncates_on_a_utf8_boundary_within_the_cap() {
        let (text, truncated) = truncate_utf8("界".repeat(400_000), MAX_OUTPUT_BYTES, false);
        assert!(truncated);
        assert!(text.len() <= MAX_OUTPUT_BYTES);
        assert!(text.ends_with(TRUNCATION_MARKER));
        assert!(text.is_char_boundary(text.len()));
    }

    #[tokio::test]
    async fn drains_and_caps_an_async_stream() {
        let input = "é".repeat(600_000);
        let (mut writer, reader) = tokio::io::duplex(input.len() + 1);
        let write = tokio::spawn(async move {
            use tokio::io::AsyncWriteExt;
            writer.write_all(input.as_bytes()).await.unwrap();
        });
        let (text, truncated) = read_capped(reader).await;
        write.await.unwrap();
        assert!(truncated);
        assert!(text.len() <= MAX_OUTPUT_BYTES);
        assert!(text.ends_with(TRUNCATION_MARKER));
    }

    #[tokio::test]
    async fn canceled_drain_retains_output_and_can_resume() {
        let (mut writer, reader) = tokio::io::duplex(64);
        writer.write_all(b"before cancellation").await.unwrap();
        let mut output = CappedOutput::new(reader);
        assert!(
            tokio::time::timeout(Duration::from_millis(20), output.drain())
                .await
                .is_err()
        );
        writer.write_all(b"; after cancellation").await.unwrap();
        drop(writer);
        output.drain().await;
        assert_eq!(
            output.finish(),
            ("before cancellation; after cancellation".into(), false)
        );
    }

    #[tokio::test]
    async fn bounded_drain_returns_with_partial_output_when_eof_stalls() {
        let (mut writer, reader) = tokio::io::duplex(64);
        writer
            .write_all(b"captured before stalled EOF")
            .await
            .unwrap();
        let mut output = CappedOutput::new(reader);
        tokio::time::timeout(
            Duration::from_secs(1),
            output.drain_for(Duration::from_millis(20)),
        )
        .await
        .expect("bounded drain must return while the writer remains open");
        let (text, truncated) = output.finish();
        assert!(truncated);
        assert_eq!(
            text,
            format!("captured before stalled EOF{TRUNCATION_MARKER}")
        );
        drop(writer);
    }

    #[tokio::test]
    async fn bounded_drain_keeps_utf8_output_within_cap() {
        let input = "界".repeat(MAX_OUTPUT_BYTES / 3 + 1);
        let (mut writer, reader) = tokio::io::duplex(input.len() + 1);
        writer.write_all(input.as_bytes()).await.unwrap();
        let mut output = CappedOutput::new(reader);
        output.drain_for(Duration::from_millis(20)).await;
        let (text, truncated) = output.finish();
        assert!(truncated);
        assert!(text.len() <= MAX_OUTPUT_BYTES);
        assert!(text.ends_with(TRUNCATION_MARKER));
        assert!(!text.contains('\u{fffd}'));
        drop(writer);
    }
}

// ADR-0028 — resource limits (rlimit) for sandboxed commands.
//
// The per-platform backends already enforce a **wall-clock** timeout (the
// `SandboxCommand.timeout` watchdog), which is the default and safest time
// control. rlimits are an *opt-in* backstop on top of that:
//
//   * `RLIMIT_CPU` (CPU-seconds) is summed across cores, so a parallel build
//     (`make -j8`) burns it far faster than wall-clock — only applied when
//     the caller sets `max_cpu_seconds` explicitly (0 = leave to the
//     wall-clock watchdog).
//   * `RLIMIT_AS` (virtual address space) is blunt: Go runtimes, jemalloc,
//     and ASAN reserve huge virtual mappings, so a low cap kills healthy
//     programs. Only applied when the caller sets `max_memory_mb` explicitly.
//
// Reference sandboxes (`openai/codex`, `anthropic-experimental/
// sandbox-runtime`) enforce neither by default for exactly these reasons;
// we mirror that and make both an informed opt-in. cgroup-v2 memory
// accounting is the correct long-term answer and is tracked as a follow-up.
//
// The value resolution is pure + host-tested; the `setrlimit` application is
// `cfg(unix)` and exercised by the per-platform integration tests on CI.

/// Resolved rlimit values. `None` = leave the limit at the inherited /
/// unlimited value (let the wall-clock watchdog handle it).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ResolvedLimits {
    /// `RLIMIT_CPU` ceiling in CPU-seconds.
    pub cpu_seconds: Option<u64>,
    /// `RLIMIT_AS` ceiling in bytes.
    pub address_space_bytes: Option<u64>,
    /// `RLIMIT_NPROC` ceiling — the process-count backstop a fork bomb trips.
    /// Only meaningful on Linux, where the bwrap user namespace makes the
    /// count per-sandbox-tree. On macOS `RLIMIT_NPROC` counts every process
    /// the login uid owns, so applying it would cap the whole session; the
    /// macOS backend never sets this field.
    pub processes: Option<u64>,
}

impl ResolvedLimits {
    /// True when no limit needs to be applied (so the backend can skip
    /// installing a `pre_exec` hook entirely).
    pub fn is_empty(&self) -> bool {
        self.cpu_seconds.is_none() && self.address_space_bytes.is_none() && self.processes.is_none()
    }
}

/// Translate the policy's `max_cpu_seconds` / `max_memory_mb` /
/// `max_processes` (0 = no cap) into concrete rlimit values. Memory MB is
/// converted to bytes with saturating arithmetic so an absurd value can't
/// overflow.
pub fn resolve_rlimits(
    max_cpu_seconds: u32,
    max_memory_mb: u32,
    max_processes: u32,
) -> ResolvedLimits {
    ResolvedLimits {
        cpu_seconds: if max_cpu_seconds == 0 {
            None
        } else {
            Some(u64::from(max_cpu_seconds))
        },
        address_space_bytes: if max_memory_mb == 0 {
            None
        } else {
            Some(u64::from(max_memory_mb).saturating_mul(1024 * 1024))
        },
        processes: if max_processes == 0 {
            None
        } else {
            Some(u64::from(max_processes))
        },
    }
}

/// Install a `pre_exec` hook on `cmd` that applies the resolved rlimits in
/// the child just before `exec`. No-op when both limits are unset.
///
/// On the Linux backend `cmd` is the `bwrap` process — rlimits are inherited
/// across the `bwrap` → target exec, so the cap lands on the sandboxed
/// command. On macOS `cmd` is `sandbox-exec`, same inheritance.
#[cfg(unix)]
pub fn apply_rlimits(cmd: &mut tokio::process::Command, limits: ResolvedLimits) {
    if limits.is_empty() {
        return;
    }
    let cpu = limits.cpu_seconds;
    let addr = limits.address_space_bytes;
    let procs = limits.processes;
    // SAFETY: the closure runs in the forked child before exec. It only calls
    // `setrlimit` (async-signal-safe) and constructs stack values — no heap
    // allocation, no locks, nothing that could deadlock a half-forked child.
    unsafe {
        cmd.pre_exec(move || {
            if let Some(secs) = cpu {
                set_one(libc::RLIMIT_CPU, secs)?;
            }
            // RLIMIT_AS is well-defined on Linux; on macOS it is unreliable
            // (aliased / absent across releases), so the address-space cap is
            // Linux-only. macOS callers still get the wall-clock watchdog +
            // RLIMIT_CPU.
            #[cfg(target_os = "linux")]
            {
                if let Some(bytes) = addr {
                    set_one(libc::RLIMIT_AS, bytes)?;
                }
                // RLIMIT_NPROC is applied under the bwrap user namespace:
                // inside it the child's uid maps to a namespace-owned uid,
                // so the counter only covers the sandboxed tree — a fork
                // bomb exhausts the cap instead of the host's task space.
                if let Some(n) = procs {
                    set_one(libc::RLIMIT_NPROC, n)?;
                }
            }
            #[cfg(not(target_os = "linux"))]
            {
                let _ = addr;
                let _ = procs;
            }
            Ok(())
        });
    }
}

/// Resource id type for `setrlimit` — glibc types it as `__rlimit_resource_t`,
/// musl (the static agent bundle) and other unices as `c_int`.
#[cfg(all(target_os = "linux", not(target_env = "musl")))]
type RlimitResource = libc::__rlimit_resource_t;
#[cfg(all(unix, not(all(target_os = "linux", not(target_env = "musl")))))]
type RlimitResource = libc::c_int;

#[cfg(unix)]
fn set_one(resource: RlimitResource, value: u64) -> std::io::Result<()> {
    let lim = libc::rlimit {
        rlim_cur: value as libc::rlim_t,
        rlim_max: value as libc::rlim_t,
    };
    // SAFETY: `lim` is a fully-initialised, correctly-typed rlimit struct.
    if unsafe { libc::setrlimit(resource, &lim) } != 0 {
        return Err(std::io::Error::last_os_error());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zero_caps_resolve_to_none() {
        let r = resolve_rlimits(0, 0, 0);
        assert!(r.is_empty());
        assert_eq!(r.cpu_seconds, None);
        assert_eq!(r.address_space_bytes, None);
        assert_eq!(r.processes, None);
    }

    #[test]
    fn cpu_seconds_pass_through() {
        let r = resolve_rlimits(30, 0, 0);
        assert_eq!(r.cpu_seconds, Some(30));
        assert_eq!(r.address_space_bytes, None);
        assert!(!r.is_empty());
    }

    #[test]
    fn memory_mb_converts_to_bytes() {
        let r = resolve_rlimits(0, 512, 0);
        assert_eq!(r.address_space_bytes, Some(512 * 1024 * 1024));
        assert_eq!(r.cpu_seconds, None);
    }

    #[test]
    fn process_cap_passes_through_and_marks_non_empty() {
        let r = resolve_rlimits(0, 0, 512);
        assert_eq!(r.processes, Some(512));
        assert_eq!(r.cpu_seconds, None);
        assert!(!r.is_empty());
    }

    #[test]
    fn all_caps_set() {
        let r = resolve_rlimits(10, 256, 64);
        assert_eq!(r.cpu_seconds, Some(10));
        assert_eq!(r.address_space_bytes, Some(256 * 1024 * 1024));
        assert_eq!(r.processes, Some(64));
    }

    #[test]
    fn absurd_memory_saturates_instead_of_overflowing() {
        let r = resolve_rlimits(0, u32::MAX, 0);
        // u32::MAX MB in bytes exceeds u32 but fits u64 — no panic, no wrap.
        assert_eq!(
            r.address_space_bytes,
            Some(u64::from(u32::MAX) * 1024 * 1024)
        );
    }
}

