//! Page tokens and page envelopes (ADR-0175 B3, after AIP-158).
//!
//! A paging command takes `pageSize` and `pageToken` and answers
//! `{items, nextPageToken}`. The token is opaque to the caller and encodes
//! whatever the arm pages by underneath: an offset into a counted store, or
//! the cursor a backend hands back. `offset` and `length` are reserved for byte
//! I/O on `read` and `write` verbs and are refused here, as are the four
//! spellings this surface used to take (`limit`, `offset`, `cursor`, `before`),
//! so a caller on the old shape learns it in one named error instead of
//! silently getting the first page.
//!
//! This module is self-contained on `serde_json::Value` so the companion
//! dispatch arms, the desktop IPC commands, and the leaf crates that implement
//! them can share it. Errors are `PagingError`, which each surface maps onto
//! its own refusal type.

use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

/// The page size used when the caller names none.
pub const DEFAULT_PAGE_SIZE: u32 = 50;
/// The largest page any command answers.
pub const MAX_PAGE_SIZE: u32 = 1_000;

/// The spellings this surface used to page by. Refused on a paging command so
/// the old shape fails loudly instead of being ignored.
pub const LEGACY_PAGING_PARAMETERS: &[&str] = &["limit", "offset", "cursor", "before"];

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum PagingError {
    #[error("pageSize must be an integer between 1 and {MAX_PAGE_SIZE}")]
    PageSize,
    #[error("pageToken is not a token this host issued")]
    PageToken,
    #[error("{0} is not a paging parameter here. Use pageSize and pageToken")]
    LegacyParameter(&'static str),
}

/// What a page token stands for. Never shown to a caller unencoded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PageToken {
    /// The next row of a counted store.
    Offset(u64),
    /// The cursor a backend handed back for its next page.
    Cursor(String),
}

impl PageToken {
    pub fn encode(&self) -> String {
        let plain = match self {
            Self::Offset(offset) => format!("o:{offset}"),
            Self::Cursor(cursor) => format!("c:{cursor}"),
        };
        URL_SAFE_NO_PAD.encode(plain)
    }

    pub fn decode(raw: &str) -> Result<Self, PagingError> {
        let bytes = URL_SAFE_NO_PAD
            .decode(raw)
            .map_err(|_| PagingError::PageToken)?;
        let plain = String::from_utf8(bytes).map_err(|_| PagingError::PageToken)?;
        if let Some(offset) = plain.strip_prefix("o:") {
            return offset
                .parse::<u64>()
                .map(Self::Offset)
                .map_err(|_| PagingError::PageToken);
        }
        if let Some(cursor) = plain.strip_prefix("c:") {
            if cursor.is_empty() {
                return Err(PagingError::PageToken);
            }
            return Ok(Self::Cursor(cursor.to_string()));
        }
        Err(PagingError::PageToken)
    }
}

/// The paging half of a request.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PageRequest {
    pub page_size: Option<u32>,
    pub page_token: Option<PageToken>,
}

impl PageRequest {
    /// Read `pageSize` and `pageToken` from a command's arguments. Refuses the
    /// legacy spellings so a caller on the old shape gets one named answer.
    pub fn from_args(args: &Value) -> Result<Self, PagingError> {
        let object = args.as_object();
        for legacy in LEGACY_PAGING_PARAMETERS {
            if object.is_some_and(|map| map.contains_key(*legacy)) {
                return Err(PagingError::LegacyParameter(legacy));
            }
        }
        let page_size = match object.and_then(|map| map.get("pageSize")) {
            None | Some(Value::Null) => None,
            Some(value) => {
                let size = value
                    .as_u64()
                    .filter(|size| (1..=u64::from(MAX_PAGE_SIZE)).contains(size))
                    .ok_or(PagingError::PageSize)?;
                Some(size as u32)
            }
        };
        let page_token = match object.and_then(|map| map.get("pageToken")) {
            None | Some(Value::Null) => None,
            Some(Value::String(raw)) if raw.is_empty() => None,
            Some(Value::String(raw)) => Some(PageToken::decode(raw)?),
            Some(_) => return Err(PagingError::PageToken),
        };
        Ok(Self {
            page_size,
            page_token,
        })
    }

    /// The desktop IPC spelling: the two parameters as the command received
    /// them.
    pub fn from_parts(
        page_size: Option<u32>,
        page_token: Option<&str>,
    ) -> Result<Self, PagingError> {
        let mut args = Map::new();
        if let Some(size) = page_size {
            args.insert("pageSize".to_string(), Value::from(size));
        }
        if let Some(token) = page_token {
            args.insert("pageToken".to_string(), Value::from(token));
        }
        Self::from_args(&Value::Object(args))
    }

    pub fn page_size_or(&self, default: u32) -> u32 {
        self.page_size.unwrap_or(default).clamp(1, MAX_PAGE_SIZE)
    }

    /// The offset an offset-paged arm starts at. A cursor token on an
    /// offset-paged command was issued by another command, so it is refused.
    pub fn offset(&self) -> Result<u64, PagingError> {
        match &self.page_token {
            None => Ok(0),
            Some(PageToken::Offset(offset)) => Ok(*offset),
            Some(PageToken::Cursor(_)) => Err(PagingError::PageToken),
        }
    }

    /// The backend cursor a cursor-paged arm continues from.
    pub fn cursor(&self) -> Result<Option<String>, PagingError> {
        match &self.page_token {
            None => Ok(None),
            Some(PageToken::Cursor(cursor)) => Ok(Some(cursor.clone())),
            Some(PageToken::Offset(_)) => Err(PagingError::PageToken),
        }
    }
}

/// One page of a collection.
///
/// Sparse rather than closed: `nextPageToken` is absent on the last page, and
/// that absence is the signal a client reads.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, schemars::JsonSchema)]
#[serde(rename_all = "camelCase")]
#[schemars(transform = crate::wire_schema::closed_sparse_object)]
// Without this every instantiation is titled `Page`, and a contract emitter
// keyed on that name publishes whichever one it hoisted last for all of them.
#[schemars(rename = "Page_of_{T}")]
pub struct Page<T> {
    pub items: Vec<T>,
    /// Present exactly when another page exists.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub next_page_token: Option<String>,
}

impl<T> Page<T> {
    /// A page from a counted store: the caller fetched `items` starting at
    /// `offset`, and `more` says whether rows remain after them.
    pub fn from_offset(items: Vec<T>, offset: u64, more: bool) -> Self {
        let next_page_token = more.then(|| PageToken::Offset(offset + items.len() as u64).encode());
        Self {
            items,
            next_page_token,
        }
    }

    /// A page from a cursor-paged backend.
    pub fn from_cursor(items: Vec<T>, next_cursor: Option<String>) -> Self {
        let next_page_token = next_cursor
            .filter(|cursor| !cursor.is_empty())
            .map(|cursor| PageToken::Cursor(cursor).encode());
        Self {
            items,
            next_page_token,
        }
    }

    /// Page an in-memory collection. This is how a bounded list that a
    /// backend returns whole answers the paging shape without changing the
    /// backend.
    pub fn slice_all(
        all: Vec<T>,
        request: &PageRequest,
        default_page_size: u32,
    ) -> Result<Self, PagingError> {
        let offset = request.offset()?;
        let page_size = request.page_size_or(default_page_size) as usize;
        let start = usize::try_from(offset).unwrap_or(usize::MAX).min(all.len());
        let end = start.saturating_add(page_size).min(all.len());
        let more = end < all.len();
        let items: Vec<T> = all.into_iter().skip(start).take(end - start).collect();
        Ok(Self::from_offset(items, offset, more))
    }

    pub fn map<U>(self, f: impl FnMut(T) -> U) -> Page<U> {
        Page {
            items: self.items.into_iter().map(f).collect(),
            next_page_token: self.next_page_token,
        }
    }
}

impl Page<Value> {
    /// A page from a legacy offset page the bridge or the direct store still
    /// answers (`{rows, total?, next_offset?, nextOffset?, has_more?}`), plus
    /// whatever extra top-level members the caller wants to keep (`total`).
    pub fn from_legacy_offset_page(
        legacy: Value,
        rows_key: &str,
        offset: u64,
        keep: &[&str],
    ) -> (Self, Map<String, Value>) {
        let mut object = match legacy {
            Value::Object(map) => map,
            other => {
                let items = match other {
                    Value::Array(items) => items,
                    _ => Vec::new(),
                };
                return (Self::from_offset(items, offset, false), Map::new());
            }
        };
        let items = match object.remove(rows_key) {
            Some(Value::Array(items)) => items,
            _ => Vec::new(),
        };
        let has_more = object.get("has_more").and_then(Value::as_bool);
        let next_offset = object
            .get("next_offset")
            .or_else(|| object.get("nextOffset"))
            .and_then(Value::as_u64);
        let more = has_more.unwrap_or(next_offset.is_some());
        let page = match next_offset {
            Some(next) if more => Self {
                items,
                next_page_token: Some(PageToken::Offset(next).encode()),
            },
            _ => Self::from_offset(items, offset, more),
        };
        let extras = keep
            .iter()
            .filter_map(|key| object.remove(*key).map(|value| ((*key).to_string(), value)))
            .collect();
        (page, extras)
    }

    /// A page from a legacy cursor page a backend still answers
    /// (`{<rows>, <nextCursor>, <hasMore>, ...}`), keeping the extra members
    /// the caller names.
    pub fn from_legacy_cursor_page(
        legacy: Value,
        rows_key: &str,
        next_cursor_key: &str,
        has_more_key: &str,
        keep: &[&str],
    ) -> (Self, Map<String, Value>) {
        let mut object = match legacy {
            Value::Object(map) => map,
            Value::Array(items) => return (Self::from_cursor(items, None), Map::new()),
            _ => return (Self::from_cursor(Vec::new(), None), Map::new()),
        };
        let items = match object.remove(rows_key) {
            Some(Value::Array(items)) => items,
            _ => Vec::new(),
        };
        let has_more = object.remove(has_more_key).and_then(|v| v.as_bool());
        let next_cursor = object
            .remove(next_cursor_key)
            .and_then(|value| match value {
                Value::String(cursor) => Some(cursor),
                Value::Number(number) => Some(number.to_string()),
                _ => None,
            });
        let page = match has_more {
            Some(false) => Self::from_cursor(items, None),
            _ => Self::from_cursor(items, next_cursor),
        };
        let extras = keep
            .iter()
            .filter_map(|key| object.remove(*key).map(|value| ((*key).to_string(), value)))
            .collect();
        (page, extras)
    }

    /// The wire document with extra top-level members (`total`,
    /// `capabilityRevision`, and the like) beside `items`.
    pub fn into_value_with(self, extras: Map<String, Value>) -> Value {
        let mut object = match serde_json::to_value(self) {
            Ok(Value::Object(map)) => map,
            _ => Map::new(),
        };
        for (key, value) in extras {
            object.entry(key).or_insert(value);
        }
        Value::Object(object)
    }
}

#[cfg(test)]
mod tests {

    #[test]
    fn each_page_instantiation_gets_its_own_schema_name() {
        // `Page<T>` is titled by its bare name unless it is told otherwise,
        // and a contract emitter keyed on that title publishes whichever
        // instantiation it hoisted last for every one of them.
        #[derive(serde::Serialize, schemars::JsonSchema)]
        struct Left {
            left: u32,
        }
        #[derive(serde::Serialize, schemars::JsonSchema)]
        struct Right {
            right: u32,
        }
        let left = serde_json::to_value(schemars::schema_for!(Page<Left>)).unwrap();
        let right = serde_json::to_value(schemars::schema_for!(Page<Right>)).unwrap();
        assert_eq!(left["title"], "Page_of_Left");
        assert_eq!(right["title"], "Page_of_Right");
        assert_ne!(left["title"], right["title"]);
    }
    use super::*;
    use serde_json::json;

    #[test]
    fn tokens_round_trip_and_reject_what_the_host_did_not_issue() {
        for token in [
            PageToken::Offset(0),
            PageToken::Offset(u64::MAX),
            PageToken::Cursor("evt-42".into()),
        ] {
            assert_eq!(PageToken::decode(&token.encode()), Ok(token));
        }
        for raw in [
            "",
            "o:12",
            "!!!",
            &URL_SAFE_NO_PAD.encode("x:1"),
            &URL_SAFE_NO_PAD.encode("o:-1"),
            &URL_SAFE_NO_PAD.encode("c:"),
        ] {
            assert_eq!(
                PageToken::decode(raw),
                Err(PagingError::PageToken),
                "{raw:?}"
            );
        }
    }

    #[test]
    fn request_reads_the_two_parameters_and_refuses_the_old_four() {
        let request = PageRequest::from_args(&json!({
            "pageSize": 25,
            "pageToken": PageToken::Offset(50).encode(),
        }))
        .unwrap();
        assert_eq!(request.page_size, Some(25));
        assert_eq!(request.offset(), Ok(50));
        assert_eq!(request.cursor(), Err(PagingError::PageToken));
        assert_eq!(
            PageRequest::from_parts(Some(25), Some(&PageToken::Offset(50).encode())),
            Ok(request)
        );

        assert_eq!(
            PageRequest::from_args(&json!({})).unwrap(),
            PageRequest::default()
        );
        assert_eq!(
            PageRequest::from_args(&json!({ "pageToken": "" })).unwrap(),
            PageRequest::default()
        );
        assert_eq!(
            PageRequest::from_args(&json!(null)).unwrap(),
            PageRequest::default()
        );

        for legacy in ["limit", "offset", "cursor", "before"] {
            assert_eq!(
                PageRequest::from_args(&json!({ legacy: 5 })),
                Err(PagingError::LegacyParameter(
                    LEGACY_PAGING_PARAMETERS
                        .iter()
                        .copied()
                        .find(|name| *name == legacy)
                        .unwrap()
                ))
            );
        }
        for size in [json!(0), json!(-1), json!(1001), json!("10"), json!(2.5)] {
            assert_eq!(
                PageRequest::from_args(&json!({ "pageSize": size })),
                Err(PagingError::PageSize),
                "{size}"
            );
        }
        assert_eq!(
            PageRequest::from_args(&json!({ "pageToken": 7 })),
            Err(PagingError::PageToken)
        );
        assert_eq!(
            PageRequest {
                page_size: Some(5_000),
                page_token: None
            }
            .page_size_or(10),
            MAX_PAGE_SIZE
        );
        assert_eq!(PageRequest::default().page_size_or(10), 10);
    }

    #[test]
    fn offset_pages_carry_a_token_exactly_when_more_remains() {
        let page = Page::from_offset(vec![1, 2, 3], 10, true);
        assert_eq!(
            page.next_page_token.as_deref().map(PageToken::decode),
            Some(Ok(PageToken::Offset(13)))
        );
        let last = Page::from_offset(vec![1], 13, false);
        assert_eq!(last.next_page_token, None);
        assert_eq!(
            serde_json::to_value(&last).unwrap(),
            json!({ "items": [1] }),
            "no token member on the last page"
        );
        let cursor = Page::from_cursor(vec!["a"], Some("next".into()));
        assert_eq!(
            cursor.next_page_token.as_deref().map(PageToken::decode),
            Some(Ok(PageToken::Cursor("next".into())))
        );
        assert_eq!(
            Page::from_cursor(vec!["a"], Some(String::new())).next_page_token,
            None
        );
    }

    #[test]
    fn slicing_a_whole_collection_walks_it_to_the_end() {
        let all: Vec<u32> = (0..7).collect();
        let mut request = PageRequest {
            page_size: Some(3),
            page_token: None,
        };
        let mut seen = Vec::new();
        loop {
            let page = Page::slice_all(all.clone(), &request, 50).unwrap();
            seen.extend(page.items.iter().copied());
            match page.next_page_token {
                Some(token) => request.page_token = Some(PageToken::decode(&token).unwrap()),
                None => break,
            }
        }
        assert_eq!(seen, all);
        // Past the end is an empty last page, not an error.
        let past = PageRequest {
            page_size: Some(3),
            page_token: Some(PageToken::Offset(99)),
        };
        let page = Page::slice_all(all, &past, 50).unwrap();
        assert!(page.items.is_empty());
        assert_eq!(page.next_page_token, None);
    }

    #[test]
    fn legacy_cursor_pages_become_pages_and_stop_when_the_backend_says_so() {
        let (page, extras) = Page::from_legacy_cursor_page(
            json!({ "messages": [1], "nextCursor": "m-9", "hasMore": true, "revision": 3 }),
            "messages",
            "nextCursor",
            "hasMore",
            &["revision"],
        );
        assert_eq!(
            page.next_page_token.as_deref().map(PageToken::decode),
            Some(Ok(PageToken::Cursor("m-9".into())))
        );
        assert_eq!(extras.get("revision"), Some(&json!(3)));
        // A cursor with hasMore false is the end, whatever the cursor says.
        let (page, _) = Page::from_legacy_cursor_page(
            json!({ "messages": [1], "nextCursor": "m-9", "hasMore": false }),
            "messages",
            "nextCursor",
            "hasMore",
            &[],
        );
        assert_eq!(page.next_page_token, None);
        // A numeric cursor is carried as text.
        let (page, _) = Page::from_legacy_cursor_page(
            json!({ "events": [], "nextSeq": 42 }),
            "events",
            "nextSeq",
            "hasMore",
            &[],
        );
        assert_eq!(
            page.next_page_token.as_deref().map(PageToken::decode),
            Some(Ok(PageToken::Cursor("42".into())))
        );
    }

    #[test]
    fn legacy_offset_pages_become_pages_and_keep_what_the_caller_asks_for() {
        let (page, extras) = Page::from_legacy_offset_page(
            json!({ "rows": [{"id": "a"}], "total": 9, "next_offset": 1, "has_more": true }),
            "rows",
            0,
            &["total"],
        );
        assert_eq!(page.items.len(), 1);
        assert_eq!(
            page.next_page_token.as_deref().map(PageToken::decode),
            Some(Ok(PageToken::Offset(1)))
        );
        assert_eq!(extras.get("total"), Some(&json!(9)));
        let value = page.into_value_with(extras);
        assert_eq!(value["total"], 9);
        assert!(value.get("rows").is_none());

        // The direct store counts and answers nextOffset without has_more.
        let (page, _) =
            Page::from_legacy_offset_page(json!({ "rows": [1, 2], "total": 2 }), "rows", 0, &[]);
        assert_eq!(page.next_page_token, None);
        // A bare array is one whole page.
        let (page, extras) = Page::from_legacy_offset_page(json!([1, 2, 3]), "rows", 0, &["x"]);
        assert_eq!(page.items.len(), 3);
        assert!(extras.is_empty());
    }
}

// Atomic-write helper used by every settings writer that overlaps with
// external tools that may also write the same file (CCSwitch ⇄ Claude Code,
// CCSwitch ⇄ Codex CLI, etc.).
//
// Two layers of safety:
//
//   1. Temp-file + rename atomic publish — the on-disk file is never partial.
//      A `.bak.<epoch_secs>` is left next to the original so the user can
//      recover if our merge logic mangles something.
//
//   2. Optional mtime check — the caller passes the `SystemTime` it observed
//      when it last *read* the file. If the current mtime differs, the file
//      has been modified by another writer since we loaded it, so our staged
//      contents are stale. We bail with `AtomicWriteError::DriftDetected`
//      and the caller re-reads + retries.
//
// The mtime check is voluntary — pass `expected_mtime: None` to disable it
// (callers that build the file from scratch can skip it).

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

/// Inputs for one atomic write. Built by callers after reading the existing
/// file (if any) so the `expected_mtime` reflects "what we saw on read".
pub struct AtomicWritePlan {
    /// Final destination path.
    pub path: PathBuf,
    /// The mtime the caller observed when it read the existing file. `None`
    /// disables the drift check entirely (useful when creating a brand-new
    /// file or when the caller explicitly wants last-writer-wins semantics).
    pub expected_mtime: Option<SystemTime>,
    /// Suffix appended after the file extension for the temp file —
    /// e.g. `"tmp"` becomes `path.with_extension("<ext>.tmp")`.
    pub tmp_suffix: String,
    /// Suffix for the pre-write backup file. A monotonic timestamp is appended.
    /// `"bak"` becomes `path.with_extension("<ext>.bak.<ts>")`.
    pub backup_suffix: String,
}

#[derive(Debug)]
pub enum AtomicWriteError {
    /// File was modified by another writer after we read it. Caller must
    /// re-read and reconcile before retrying.
    DriftDetected {
        expected: SystemTime,
        current: SystemTime,
    },
    /// All other underlying I/O / OS errors.
    Io(std::io::Error),
}

impl std::fmt::Display for AtomicWriteError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AtomicWriteError::DriftDetected { expected, current } => {
                let exp = expected.duration_since(UNIX_EPOCH).ok();
                let cur = current.duration_since(UNIX_EPOCH).ok();
                write!(
                    f,
                    "drift_detected: file mtime changed since read (expected {exp:?}, current {cur:?})"
                )
            }
            AtomicWriteError::Io(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for AtomicWriteError {}

impl From<std::io::Error> for AtomicWriteError {
    fn from(e: std::io::Error) -> Self {
        AtomicWriteError::Io(e)
    }
}

/// Sentinel string the renderer matches on for the "another tool wrote
/// this file while we were preparing the patch" case. Keep the literal in
/// sync with the frontend's `provider-switch-dialog` drift handling.
pub const DRIFT_DETECTED_TAG: &str = "drift_detected";

/// Result of a successful atomic write.
#[derive(Debug)]
pub struct AtomicWriteResult {
    /// Destination path (echoed back).
    pub path: PathBuf,
    /// Backup path that was created, when the destination already existed.
    pub backup_path: Option<PathBuf>,
}

fn unique_backup_stamp() -> u64 {
    static LAST_BACKUP_STAMP: AtomicU64 = AtomicU64::new(0);
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos().min(u64::MAX as u128) as u64)
        .unwrap_or(0);

    loop {
        let last = LAST_BACKUP_STAMP.load(Ordering::Relaxed);
        let next = if now > last {
            now
        } else {
            last.saturating_add(1)
        };
        if LAST_BACKUP_STAMP
            .compare_exchange(last, next, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
        {
            return next;
        }
    }
}

/// Select one non-existing temporary sibling of an already-authorized target.
/// Scope ownership stays with the caller; this function never grants a parent
/// directory or creates a file. Writers must still open with create_new.
pub fn scoped_temporary_sibling(
    target: &Path,
    nonce: &str,
    is_allowed: impl Fn(&Path) -> bool,
) -> std::io::Result<PathBuf> {
    use std::io::{Error, ErrorKind};
    if !target.is_absolute()
        || target
            .components()
            .any(|part| matches!(part, std::path::Component::ParentDir))
        || nonce.len() != 32
        || !nonce.bytes().all(|byte| byte.is_ascii_hexdigit())
    {
        return Err(Error::new(
            ErrorKind::InvalidInput,
            "invalid backup target or nonce",
        ));
    }
    let name = target
        .file_name()
        .ok_or_else(|| Error::new(ErrorKind::InvalidInput, "backup target must name a file"))?;
    if !is_allowed(target) {
        return Err(Error::new(
            ErrorKind::PermissionDenied,
            "backup target is outside filesystem scope",
        ));
    }
    let parent = fs::canonicalize(
        target
            .parent()
            .ok_or_else(|| Error::new(ErrorKind::InvalidInput, "backup target has no parent"))?,
    )?;
    let resolved_target = parent.join(name);
    if !is_allowed(&resolved_target) {
        return Err(Error::new(
            ErrorKind::PermissionDenied,
            "resolved backup target is outside filesystem scope",
        ));
    }
    match fs::symlink_metadata(&resolved_target) {
        Ok(metadata) if !metadata.file_type().is_file() => {
            return Err(Error::new(
                ErrorKind::InvalidInput,
                "backup target must be a regular file",
            ));
        }
        Ok(_) => {}
        Err(error) if error.kind() == ErrorKind::NotFound => {}
        Err(error) => return Err(error),
    }
    let temporary = parent.join(format!(".cognia-backup-{nonce}.partial"));
    match fs::symlink_metadata(&temporary) {
        Ok(_) => Err(Error::new(
            ErrorKind::AlreadyExists,
            "backup temporary path already exists",
        )),
        Err(error) if error.kind() == ErrorKind::NotFound => Ok(temporary),
        Err(error) => Err(error),
    }
}

/// Atomically write `contents` to `plan.path`, optionally checking that the
/// destination's mtime still matches what the caller observed on read.
///
/// Order of operations:
///   1. Compare mtime (if expected_mtime is Some).
///   2. Copy current file (if any) to `<path>.<ext>.bak.<epoch_secs>`.
///   3. Write contents to `<path>.<ext>.tmp` and fsync.
///   4. Rename tmp into place.
///
/// On failure at any step beyond (1), the tmp file is best-effort cleaned up.
pub fn atomic_write_with_mtime_check(
    plan: &AtomicWritePlan,
    contents: &[u8],
) -> Result<AtomicWriteResult, AtomicWriteError> {
    atomic_write_with_sync(plan, contents, fs::File::sync_all)
}

fn atomic_write_with_sync(
    plan: &AtomicWritePlan,
    contents: &[u8],
    sync_file: impl FnOnce(&fs::File) -> std::io::Result<()>,
) -> Result<AtomicWriteResult, AtomicWriteError> {
    atomic_write_impl(plan, contents, sync_file, false)
}

/// Credential-bearing config writes: private staging and backup files on Unix.
/// `None` asserts the destination is absent, rather than disabling drift checks.
pub fn atomic_write_private_with_mtime_check(
    plan: &AtomicWritePlan,
    contents: &[u8],
) -> Result<AtomicWriteResult, AtomicWriteError> {
    atomic_write_impl(plan, contents, fs::File::sync_all, true)
}

fn private_new_file(path: &Path) -> std::io::Result<fs::File> {
    let mut options = fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    options.open(path)
}

#[cfg(test)]
mod private_write_tests {
    use super::*;

    #[test]
    fn private_config_keeps_backup_and_rejects_stale_or_missing_preconditions() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("settings.json");
        fs::write(&path, "old credential").unwrap();
        let modified = fs::metadata(&path).unwrap().modified().unwrap();
        let plan = AtomicWritePlan {
            path: path.clone(),
            expected_mtime: Some(modified),
            tmp_suffix: "private-test".into(),
            backup_suffix: "gateway-bak".into(),
        };
        let result = atomic_write_private_with_mtime_check(&plan, b"new credential").unwrap();
        assert_eq!(fs::read_to_string(&path).unwrap(), "new credential");
        let backup = result.backup_path.unwrap();
        assert_eq!(fs::read_to_string(&backup).unwrap(), "old credential");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                fs::metadata(&path).unwrap().permissions().mode() & 0o777,
                0o600
            );
            assert_eq!(
                fs::metadata(backup).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }
        let missing = AtomicWritePlan {
            expected_mtime: None,
            ..plan
        };
        assert!(matches!(
            atomic_write_private_with_mtime_check(&missing, b"overwrite"),
            Err(AtomicWriteError::DriftDetected { .. })
        ));
        assert_eq!(fs::read_to_string(path).unwrap(), "new credential");
    }

    #[test]
    fn private_config_creates_a_missing_destination_without_overwrite() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("new.json");
        let plan = AtomicWritePlan {
            path: path.clone(),
            expected_mtime: None,
            tmp_suffix: "private-test".into(),
            backup_suffix: "gateway-bak".into(),
        };
        assert!(atomic_write_private_with_mtime_check(&plan, b"created")
            .unwrap()
            .backup_path
            .is_none());
        assert_eq!(fs::read_to_string(path).unwrap(), "created");
    }
}

fn atomic_write_impl(
    plan: &AtomicWritePlan,
    contents: &[u8],
    sync_file: impl FnOnce(&fs::File) -> std::io::Result<()>,
    private: bool,
) -> Result<AtomicWriteResult, AtomicWriteError> {
    if private && plan.expected_mtime.is_none() && plan.path.exists() {
        return Err(AtomicWriteError::DriftDetected {
            expected: SystemTime::UNIX_EPOCH,
            current: fs::metadata(&plan.path)?.modified()?,
        });
    }
    // 1. mtime drift check.
    if let Some(expected) = plan.expected_mtime {
        if plan.path.exists() {
            let meta = fs::metadata(&plan.path)?;
            let current = meta.modified()?;
            if !mtimes_equal(expected, current) {
                return Err(AtomicWriteError::DriftDetected { expected, current });
            }
        }
        // If the caller asserted a specific mtime and the file is now gone,
        // that's also drift: someone deleted it between read and write.
        else {
            return Err(AtomicWriteError::DriftDetected {
                expected,
                current: SystemTime::UNIX_EPOCH,
            });
        }
    }

    // Resolve the suffix-stamped backup / tmp paths.
    let ext = plan.path.extension().and_then(|s| s.to_str()).unwrap_or("");
    let backup_path = if plan.path.exists() {
        let ts = unique_backup_stamp();
        // Always prepend the original extension so "<file>.json.bak.<ts>" is
        // the canonical shape. Empty extensions degrade gracefully to
        // "<file>.bak.<ts>".
        let suffix = if ext.is_empty() {
            format!("{}.{}", plan.backup_suffix, ts)
        } else {
            format!("{}.{}.{}", ext, plan.backup_suffix, ts)
        };
        let bp = plan.path.with_extension(suffix);
        if private {
            let mut backup = private_new_file(&bp)?;
            backup.write_all(&fs::read(&plan.path)?)?;
            backup.sync_all()?;
        } else {
            fs::copy(&plan.path, &bp)?;
        }
        Some(bp)
    } else {
        None
    };

    // 3. Stage to tmp + fsync.
    let tmp_suffix = if ext.is_empty() {
        plan.tmp_suffix.clone()
    } else {
        format!("{}.{}", ext, plan.tmp_suffix)
    };
    let tmp_path = plan.path.with_extension(tmp_suffix);
    let mut file = if private {
        private_new_file(&tmp_path)?
    } else {
        fs::File::create(&tmp_path)?
    };
    let staged = file.write_all(contents).and_then(|()| sync_file(&file));
    // Close before cleanup so a failed write/sync can release its temporary
    // file on platforms that forbid removing open files.
    drop(file);
    if let Err(error) = staged {
        let _ = fs::remove_file(&tmp_path);
        return Err(AtomicWriteError::Io(error));
    }

    // 4. Rename atomically.
    // Recheck after staging: a concurrent client may have saved while the
    // backup or fsync was running. Missing destinations publish without replace.
    if private {
        if let Some(expected) = plan.expected_mtime {
            let current = fs::metadata(&plan.path)
                .and_then(|meta| meta.modified())
                .unwrap_or(SystemTime::UNIX_EPOCH);
            if !mtimes_equal(expected, current) {
                let _ = fs::remove_file(&tmp_path);
                return Err(AtomicWriteError::DriftDetected { expected, current });
            }
        }
    }
    let published = if private && plan.expected_mtime.is_none() {
        fs::hard_link(&tmp_path, &plan.path).and_then(|()| fs::remove_file(&tmp_path))
    } else {
        fs::rename(&tmp_path, &plan.path)
    };
    if let Err(e) = published {
        // Best-effort cleanup.
        let _ = fs::remove_file(&tmp_path);
        return Err(AtomicWriteError::Io(e));
    }

    Ok(AtomicWriteResult {
        path: plan.path.clone(),
        backup_path,
    })
}

/// Prune `<file>.<ext>.bak.<timestamp>` backups left by
/// `atomic_write_with_mtime_check`, keeping the `keep` most-recent ones and
/// deleting the rest (oldest-first). The active file at `path` is never
/// touched. `keep == 0` removes every backup.
///
/// Matching is intentionally narrow: only sibling files whose name is
/// `<path file_name>.bak.<digits>` are considered backups. This is the exact
/// shape the atomic writer produces (`with_extension("<ext>.bak.<ts>")`),
/// so unrelated files in the directory are never deleted.
///
/// Best-effort: I/O errors enumerating or removing individual entries are
/// swallowed so a failed rotation never aborts the surrounding write. Returns
/// the list of paths that were removed (useful for tests / logging).
pub fn rotate_backups(path: &Path, keep: usize) -> Vec<PathBuf> {
    let dir = match path.parent() {
        Some(d) => d,
        None => return Vec::new(),
    };
    let file_name = match path.file_name().and_then(|s| s.to_str()) {
        Some(n) => n,
        None => return Vec::new(),
    };
    // Backups are "<file_name>.bak.<epoch_secs>". We capture the trailing
    // timestamp to sort by; the suffix after the last '.' must be all-digits.
    let prefix = format!("{file_name}.bak.");

    let mut backups: Vec<(u64, PathBuf)> = Vec::new();
    let read_dir = match fs::read_dir(dir) {
        Ok(rd) => rd,
        Err(_) => return Vec::new(),
    };
    for entry in read_dir.flatten() {
        let name_os = entry.file_name();
        let name = match name_os.to_str() {
            Some(n) => n,
            None => continue,
        };
        let Some(ts_str) = name.strip_prefix(&prefix) else {
            continue;
        };
        // Guard against matching e.g. "<file>.bak.5.tmp" — require a pure
        // numeric tail so only canonical backups are candidates for deletion.
        let Ok(ts) = ts_str.parse::<u64>() else {
            continue;
        };
        backups.push((ts, entry.path()));
    }

    if backups.len() <= keep {
        return Vec::new();
    }

    // Sort newest-first by timestamp; tie-break on path for determinism on
    // filesystems that collapse multiple writes into the same second.
    backups.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| b.1.cmp(&a.1)));

    let mut removed = Vec::new();
    for (_, p) in backups.into_iter().skip(keep) {
        if fs::remove_file(&p).is_ok() {
            removed.push(p);
        }
    }
    removed
}

/// Read a file and return its raw bytes + the mtime observed at read time.
/// Returns `Ok((bytes, mtime))` if the file exists, `Ok((vec![], None))` if
/// it doesn't (callers building from scratch).
pub fn read_with_mtime(path: &Path) -> Result<(Vec<u8>, Option<SystemTime>), std::io::Error> {
    match fs::metadata(path) {
        Ok(meta) => {
            let mtime = meta.modified().ok();
            let bytes = fs::read(path)?;
            Ok((bytes, mtime))
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok((Vec::new(), None)),
        Err(e) => Err(e),
    }
}

/// mtime comparison with a small tolerance — some filesystems only resolve
/// to seconds (FAT32, some NFS), so we treat differences < 1ms as equal.
/// This guards against false positives when a caller reads + writes in the
/// same millisecond.
fn mtimes_equal(a: SystemTime, b: SystemTime) -> bool {
    if a == b {
        return true;
    }
    let delta = a.duration_since(b).or_else(|_| b.duration_since(a));
    matches!(delta, Ok(d) if d.as_millis() < 1)
}

