        );
        assert_eq!(
            scoped_temporary_sibling(&target, &"b".repeat(32), |path| path == dir)
                .unwrap_err()
                .kind(),
            std::io::ErrorKind::PermissionDenied
        );
        fs::remove_dir_all(dir).unwrap();
    }

