fn audit_retry_after_matches_the_remaining_token_deficit() {
    let limiter = RateLimiter::new(RateLimitConfig {capacity: 1.0, refill_per_sec: 0.25});
    let start = Instant::now();
    assert!(matches!(limiter.check_at("audit", start), RateLimitDecision::Accept));
    match limiter.check_at("audit", start) {
      RateLimitDecision::Reject {retry_after} => assert_eq!(retry_after, Duration::from_secs(4)),
      _ => panic!("empty bucket must reject"),
    }
    match limiter.check_at("audit", start + Duration::from_secs(2)) {
      RateLimitDecision::Reject {retry_after} => assert_eq!(retry_after, Duration::from_secs(2)),
      _ => panic!("half-refilled bucket must reject"),
    }
    assert!(matches!(limiter.check_at("audit", start + Duration::from_secs(4)), RateLimitDecision::Accept));
}

