//! Per-device rate limiting (Wave 3.3) — in-house token bucket.
//!
//! `tower_governor` would be the ideal off-the-shelf choice, but we
//! avoid the new crate dep and roll a focused implementation: per-
//! device buckets keyed by `DeviceContext::device_id`, refill once per
//! call from the elapsed wall-clock, and a hard burst ceiling.
//!
//! Defaults: `60 requests/minute` with a `10` request burst — i.e.
//! `1.0` token per second, max `10` tokens. Loopback / unauthenticated
//! pre-pair traffic is intentionally not rate-limited; the limiter
//! lives downstream of the JWT verifier middleware so only paired
//! clients are gated.
//!
//! Read-only commands get a second, far wider bucket, because a paired
//! client's first act is a burst this one cannot fit. `runSyncDown`
//! walks 25 sync handlers back to back, and each one pages until the
//! server stops setting `has_more` — so a first pairing is 25 calls at
//! the floor and considerably more once `sessions` and `messages`
//! paginate. Against a 10-token bucket refilling at 1/s, everything
//! past the tenth call is rejected, and the client's three-attempt
//! sub-second backoff expires long before the bucket recovers: the tail
//! tables end up empty, silently, since `runSyncDown` records the error
//! per table and moves on.
//!
//! This is the same reasoning that already exempts the `service`
//! principal at the RPC gate ("performs a large deterministic bootstrap
//! burst, so charging it against a 10-request device bucket leaves
//! runtimes half-initialized") — a paired device performs that burst
//! too. Splitting by class keeps the strict bucket where it earns its
//! keep, on the mutating commands.
//!
//! On rejection the helper returns the precise wait time so the caller
//! can populate `Retry-After`.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};

use parking_lot::Mutex;

/// Per-device token bucket. Tokens replenish at `refill_per_sec` until
/// `capacity` is reached. A successful call subtracts one token.
#[derive(Debug, Clone, Copy)]
struct Bucket {
    tokens: f64,
    last_refill: Instant,
}

impl Bucket {
    fn new(capacity: f64, now: Instant) -> Self {
        Self {
            tokens: capacity,
            last_refill: now,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct RateLimitConfig {
    /// Maximum tokens a bucket can hold (burst size).
    pub capacity: f64,
    /// Tokens added per second of wall-clock.
    pub refill_per_sec: f64,
}

impl Default for RateLimitConfig {
    fn default() -> Self {
        // 60 rpm with 10-burst.
        Self {
            capacity: 10.0,
            refill_per_sec: 1.0,
        }
    }
}

impl RateLimitConfig {
    /// The read-only bucket: 600 rpm with a 120 burst.
    ///
    /// Sized from the one burst that actually exists rather than a round
    /// number. The sync bootstrap is 25 handlers, each paging while the
    /// server sets `has_more`; 120 leaves roughly four pages per table
    /// before anything is refused, and the 10/s refill means even a much
    /// larger first pull drains at a rate no human notices. Reads are
    /// cheap and idempotent — the bucket that has to stay tight is the
    /// mutating one, and it does.
    pub fn read_only_default() -> Self {
        Self {
            capacity: 120.0,
            refill_per_sec: 10.0,
        }
    }
}

/// Which bucket a request is charged to.
///
/// The split is by cost and blast radius, not by endpoint: a read cannot
/// change anything, so a client burst of them is a throughput question.
/// A write can, so it stays on the strict bucket.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RequestClass {
    /// Charged to the wide bucket — `READ_ONLY_COMMANDS_SET` members.
    ReadOnly,
    /// Charged to the strict bucket. The default for anything unclassified.
    Mutating,
    /// Bounded reads of caller-owned media transfers, never FFmpeg jobs.
    MediaTransfer,
}

pub struct RateLimiter {
    config: RateLimitConfig,
    read_config: RateLimitConfig,
    buckets: Mutex<HashMap<String, Bucket>>,
    read_buckets: Mutex<HashMap<String, Bucket>>,
    media_transfer_buckets: Mutex<HashMap<String, Bucket>>,
}

#[derive(Debug, Clone, Copy)]
pub enum RateLimitDecision {
    /// Request accepted; one token deducted.
    Accept,
    /// Request rejected; client should retry after this duration.
    Reject { retry_after: Duration },
}

impl RateLimiter {
    pub fn new(config: RateLimitConfig) -> Arc<Self> {
        Self::with_classes(config, RateLimitConfig::read_only_default())
    }

    /// Both buckets, for tests that need to drive them independently.
    pub fn with_classes(config: RateLimitConfig, read_config: RateLimitConfig) -> Arc<Self> {
        Arc::new(Self {
            config,
            read_config,
            buckets: Mutex::new(HashMap::new()),
            read_buckets: Mutex::new(HashMap::new()),
            media_transfer_buckets: Mutex::new(HashMap::new()),
        })
    }

    pub fn with_defaults() -> Arc<Self> {
        Self::new(RateLimitConfig::default())
    }

    /// Take one token for `device_id` from the strict bucket.
    ///
    /// Kept as the unclassified entry point so a caller that has not
    /// reasoned about cost gets the conservative answer.
    pub fn check(&self, device_id: &str) -> RateLimitDecision {
        self.check_class(device_id, RequestClass::Mutating)
    }

    /// Take one token from the bucket this request's class is charged to.
    pub fn check_class(&self, device_id: &str, class: RequestClass) -> RateLimitDecision {
        self.check_class_at(device_id, class, Instant::now())
    }

    #[cfg(test)]
    fn check_at(&self, device_id: &str, now: Instant) -> RateLimitDecision {
        self.check_class_at(device_id, RequestClass::Mutating, now)
    }

    fn check_class_at(
        &self,
        device_id: &str,
        class: RequestClass,
        now: Instant,
    ) -> RateLimitDecision {
        let (cfg, mut buckets) = match class {
            RequestClass::ReadOnly => (self.read_config, self.read_buckets.lock()),
            RequestClass::Mutating => (self.config, self.buckets.lock()),
            // Two 128 MiB exports at 64 KiB per chunk fit one burst. Keeping
            // transfer traffic separate prevents downloads from starving UI
            // reads. Ownership, per-chunk bounds and transfer memory limits
            // are still enforced by the media registry before reading bytes.
            RequestClass::MediaTransfer => (
                RateLimitConfig {
                    capacity: 4_096.0,
                    refill_per_sec: 64.0,
                },
                self.media_transfer_buckets.lock(),
            ),
        };
        let bucket = buckets
            .entry(device_id.to_string())
            .or_insert_with(|| Bucket::new(cfg.capacity, now));

        // Refill: tokens grow proportionally to elapsed seconds, capped.
        let elapsed = now.saturating_duration_since(bucket.last_refill);
        let added = elapsed.as_secs_f64() * cfg.refill_per_sec;
        bucket.tokens = (bucket.tokens + added).min(cfg.capacity);
        bucket.last_refill = now;

        if bucket.tokens >= 1.0 {
            bucket.tokens -= 1.0;
            RateLimitDecision::Accept
        } else {
            // Need (1 - tokens) more tokens, each takes 1/refill_per_sec.
            let deficit = 1.0 - bucket.tokens;
            let secs = deficit / cfg.refill_per_sec;
            // Ceil to whole seconds for Retry-After (HTTP only allows
            // integer-second precision on the spec) — minimum 1 s.
            let wait = secs.max(0.001).ceil() as u64;
            RateLimitDecision::Reject {
                retry_after: Duration::from_secs(wait.max(1)),
            }
        }
    }

    /// Test-only — count of distinct devices currently holding a bucket.
    #[cfg(any(test, feature = "test-support"))]
    pub fn bucket_count(&self) -> usize {
        self.buckets.lock().len()
    }

    /// Test-only — the same count for the read-only bucket.
    #[cfg(any(test, feature = "test-support"))]
    pub fn read_bucket_count(&self) -> usize {
        self.read_buckets.lock().len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn first_request_for_a_new_device_is_accepted() {
        let limiter = RateLimiter::with_defaults();
        match limiter.check("dev-1") {
            RateLimitDecision::Accept => {}
            RateLimitDecision::Reject { .. } => panic!("first request should accept"),
        }
        assert_eq!(limiter.bucket_count(), 1);
    }

    #[test]
    fn burst_is_bounded_by_capacity() {
        let limiter = RateLimiter::new(RateLimitConfig {
            capacity: 3.0,
            refill_per_sec: 1.0,
        });
        let now = Instant::now();
        for i in 0..3 {
            let d = limiter.check_at("dev", now);
            assert!(
                matches!(d, RateLimitDecision::Accept),
                "request {i} accepted"
            );
        }
        let denied = limiter.check_at("dev", now);
        match denied {
            RateLimitDecision::Reject { retry_after } => {
                assert!(retry_after.as_secs() >= 1);
            }
            RateLimitDecision::Accept => panic!("4th request must reject"),
        }
    }

    #[test]
    fn refill_unblocks_after_enough_wall_clock() {
        let limiter = RateLimiter::new(RateLimitConfig {
            capacity: 1.0,
            refill_per_sec: 1.0,
        });
        let t0 = Instant::now();
        assert!(matches!(
            limiter.check_at("dev", t0),
            RateLimitDecision::Accept
        ));
        // Same instant: bucket empty.
        assert!(matches!(
            limiter.check_at("dev", t0),
            RateLimitDecision::Reject { .. }
        ));
        // 2 seconds later: should be back at capacity.
        let t1 = t0 + Duration::from_secs(2);
        assert!(matches!(
            limiter.check_at("dev", t1),
            RateLimitDecision::Accept
        ));
    }

    // The regression this class split exists for: a paired client's first
    // act is `runSyncDown`, 25 sync_pull calls back to back (more once a
    // table pages). On the strict bucket everything past the tenth was
    // refused, and the tail tables silently stayed empty.
    #[test]
    fn a_sync_bootstrap_burst_fits_in_the_read_only_bucket() {
        let limiter = RateLimiter::with_defaults();
        let now = Instant::now();
        // 25 handlers, four pages each — comfortably past what the strict
        // bucket holds, and still inside the read-only one.
        for i in 0..100 {
            assert!(
                matches!(
                    limiter.check_class_at("dev", RequestClass::ReadOnly, now),
                    RateLimitDecision::Accept
                ),
                "read {i} of the bootstrap burst must be accepted"
            );
        }
    }

    #[test]
    fn the_same_burst_is_still_refused_on_the_mutating_bucket() {
        let limiter = RateLimiter::with_defaults();
        let now = Instant::now();
        for _ in 0..10 {
            assert!(matches!(
                limiter.check_class_at("dev", RequestClass::Mutating, now),
                RateLimitDecision::Accept
            ));
        }
        assert!(
            matches!(
                limiter.check_class_at("dev", RequestClass::Mutating, now),
                RateLimitDecision::Reject { .. }
            ),
            "writes keep the strict 10-token ceiling"
        );
    }

    #[test]
    fn the_two_classes_do_not_spend_each_others_tokens() {
        let limiter = RateLimiter::with_defaults();
        let now = Instant::now();
        // Drain the strict bucket entirely.
        for _ in 0..10 {
            let _ = limiter.check_class_at("dev", RequestClass::Mutating, now);
        }
        assert!(matches!(
            limiter.check_class_at("dev", RequestClass::Mutating, now),
            RateLimitDecision::Reject { .. }
        ));
        // A read is unaffected, and vice versa.
        assert!(matches!(
            limiter.check_class_at("dev", RequestClass::ReadOnly, now),
            RateLimitDecision::Accept
        ));
        assert_eq!(limiter.bucket_count(), 1);
        assert_eq!(limiter.read_bucket_count(), 1);
    }

    #[test]
    fn the_read_only_bucket_still_has_a_ceiling() {
        let limiter = RateLimiter::with_classes(
            RateLimitConfig::default(),
            RateLimitConfig {
                capacity: 2.0,
                refill_per_sec: 10.0,
            },
        );
        let now = Instant::now();
        for _ in 0..2 {
            assert!(matches!(
                limiter.check_class_at("dev", RequestClass::ReadOnly, now),
                RateLimitDecision::Accept
            ));
        }
        match limiter.check_class_at("dev", RequestClass::ReadOnly, now) {
            RateLimitDecision::Reject { retry_after } => {
                // Never sub-second: the wait is what the client is told to
                // sleep, and HTTP only carries whole seconds.
                assert!(retry_after.as_secs() >= 1);
            }
            RateLimitDecision::Accept => panic!("the read bucket must still bound a burst"),
        }
    }

    #[test]
    fn plain_check_stays_on_the_strict_bucket() {
        let limiter = RateLimiter::with_defaults();
        let now = Instant::now();
        for _ in 0..10 {
            let _ = limiter.check_at("dev", now);
        }
        assert!(
            matches!(
                limiter.check_at("dev", now),
                RateLimitDecision::Reject { .. }
            ),
            "an unclassified caller must not silently get the wide bucket"
        );
        assert_eq!(limiter.read_bucket_count(), 0);
    }

    #[test]
    fn distinct_devices_have_independent_buckets() {
        let limiter = RateLimiter::new(RateLimitConfig {
            capacity: 1.0,
            refill_per_sec: 1.0,
        });
        let t0 = Instant::now();
        assert!(matches!(
            limiter.check_at("a", t0),
            RateLimitDecision::Accept
        ));
        assert!(matches!(
            limiter.check_at("b", t0),
            RateLimitDecision::Accept
        ));
        // Each device has its own bucket — neither blocks the other on
        // first call.
        assert!(matches!(
            limiter.check_at("a", t0),
            RateLimitDecision::Reject { .. }
        ));
        assert!(matches!(
            limiter.check_at("b", t0),
            RateLimitDecision::Reject { .. }
        ));
        assert_eq!(limiter.bucket_count(), 2);
    }

    #[test]
    fn media_downloads_have_a_bounded_independent_transfer_budget() {
        let limiter = RateLimiter::with_defaults();
        let now = Instant::now();
        for _ in 0..4_096 {
            assert!(matches!(
                limiter.check_class_at("media-device", RequestClass::MediaTransfer, now),
                RateLimitDecision::Accept
            ));
        }
        assert!(matches!(
            limiter.check_class_at("media-device", RequestClass::MediaTransfer, now),
            RateLimitDecision::Reject { .. }
        ));
        for class in [RequestClass::ReadOnly, RequestClass::Mutating] {
            assert!(matches!(
                limiter.check_class_at("media-device", class, now),
                RateLimitDecision::Accept
            ));
        }
        assert!(matches!(
            limiter.check_class_at("another-device", RequestClass::MediaTransfer, now),
            RateLimitDecision::Accept
        ));
        let later = now + Duration::from_secs(1);
        for _ in 0..64 {
            assert!(matches!(
                limiter.check_class_at("media-device", RequestClass::MediaTransfer, later),
                RateLimitDecision::Accept
            ));
        }
        assert!(matches!(
            limiter.check_class_at("media-device", RequestClass::MediaTransfer, later),
            RateLimitDecision::Reject { .. }
        ));
    }
}

//! Generation-aware cancellation for request ids reused across async calls.

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;
use std::time::{Duration, Instant};

use tokio::sync::oneshot;

struct Entry {
    generation: u64,
    sender: oneshot::Sender<()>,
}

/// A request-id registry that prevents an older request's cleanup from
/// unregistering a newer request that reused the same id.
#[derive(Default)]
pub struct RequestCancellationRegistry {
    next_generation: AtomicU64,
    entries: Mutex<HashMap<String, Entry>>,
}

impl RequestCancellationRegistry {
    /// Register `request_id`, cancelling any previous owner of that id.
    pub fn register(&self, request_id: &str) -> (u64, oneshot::Receiver<()>) {
        let generation = self.next_generation.fetch_add(1, Ordering::Relaxed);
        let (sender, receiver) = oneshot::channel();
        let previous = self.entries.lock().ok().and_then(|mut entries| {
            entries
                .insert(request_id.to_string(), Entry { generation, sender })
                .map(|entry| entry.sender)
        });
        if let Some(previous) = previous {
            let _ = previous.send(());
        }
        (generation, receiver)
    }

    /// Cancel the current owner of `request_id`.
    pub fn cancel(&self, request_id: &str) -> bool {
        self.entries
            .lock()
            .ok()
            .and_then(|mut entries| entries.remove(request_id))
            .is_some_and(|entry| entry.sender.send(()).is_ok())
    }

    /// Remove a completed registration only if it is still the current owner.
    pub fn finish(&self, request_id: &str, generation: u64) {
        if let Ok(mut entries) = self.entries.lock() {
            if entries
                .get(request_id)
                .is_some_and(|entry| entry.generation == generation)
            {
                entries.remove(request_id);
            }
        }
    }
}

struct Admission {
    token: String,
    expires: Instant,
    sender: Option<oneshot::Sender<()>>,
    receiver: Option<oneshot::Receiver<()>>,
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum RequestAdmissionError {
    #[error("request_admission_invalid")]
    Invalid,
    #[error("request_admission_full")]
    Full,
    #[error("request_admission_stale")]
    Stale,
}

/// Explicit, bounded admission for a caller that waits for prepare before send.
/// Tokens are generated by the owning host. Unknown/expired claims fail closed;
/// forgetting a reservation therefore never turns a cancelled request into I/O.
pub struct RequestAdmissionRegistry {
    entries: Mutex<HashMap<String, Admission>>,
    capacity: usize,
    ttl: Duration,
}

impl Default for RequestAdmissionRegistry {
    fn default() -> Self {
        Self {
            entries: Mutex::new(HashMap::new()),
            capacity: 256,
            ttl: Duration::from_secs(30),
        }
    }
}

impl RequestAdmissionRegistry {
    pub fn prepare(&self, request_id: &str, token: &str) -> Result<(), RequestAdmissionError> {
        self.prepare_at(request_id, token, Instant::now())
    }

    fn prepare_at(
        &self,
        request_id: &str,
        token: &str,
        now: Instant,
    ) -> Result<(), RequestAdmissionError> {
        if request_id.is_empty() || request_id.len() > 128 || token.is_empty() || token.len() > 128
        {
            return Err(RequestAdmissionError::Invalid);
        }
        let mut entries = self
            .entries
            .lock()
            .map_err(|_| RequestAdmissionError::Stale)?;
        entries.retain(|_, entry| entry.receiver.is_none() || entry.expires > now);
        if !entries.contains_key(request_id) && entries.len() >= self.capacity {
            return Err(RequestAdmissionError::Full);
        }
        let (sender, receiver) = oneshot::channel();
        if let Some(previous) = entries.insert(
            request_id.to_string(),
            Admission {
                token: token.to_string(),
                expires: now + self.ttl,
                sender: Some(sender),
                receiver: Some(receiver),
            },
        ) {
            if let Some(sender) = previous.sender {
                let _ = sender.send(());
            }
        }
        Ok(())
    }

    pub fn claim(
        &self,
        request_id: &str,
        token: &str,
    ) -> Result<(RequestAdmissionGuard<'_>, oneshot::Receiver<()>), RequestAdmissionError> {
        self.claim_at(request_id, token, Instant::now())
    }

    fn claim_at(
        &self,
        request_id: &str,
        token: &str,
        now: Instant,
    ) -> Result<(RequestAdmissionGuard<'_>, oneshot::Receiver<()>), RequestAdmissionError> {
        let mut entries = self
            .entries
            .lock()
            .map_err(|_| RequestAdmissionError::Stale)?;
        entries.retain(|_, entry| entry.receiver.is_none() || entry.expires > now);
        let entry = entries
            .get_mut(request_id)
            .filter(|entry| entry.token == token)
            .ok_or(RequestAdmissionError::Stale)?;
        let receiver = entry.receiver.take().ok_or(RequestAdmissionError::Stale)?;
        Ok((
            RequestAdmissionGuard {
                registry: self,
                request_id: request_id.to_string(),
                token: token.to_string(),
            },
            receiver,
        ))
    }

    pub fn cancel(&self, request_id: &str, token: &str) -> bool {
        let removed = self.entries.lock().ok().and_then(|mut entries| {
            if entries
                .get(request_id)
                .is_some_and(|entry| entry.token == token)
            {
                entries.remove(request_id)
            } else {
                None
            }
        });
        if let Some(mut entry) = removed {
            if let Some(sender) = entry.sender.take() {
                let _ = sender.send(());
            }
            true
        } else {
            false
        }
    }

    fn finish(&self, request_id: &str, token: &str) {
        if let Ok(mut entries) = self.entries.lock() {
            if entries
                .get(request_id)
                .is_some_and(|entry| entry.token == token)
            {
                entries.remove(request_id);
            }
        }
    }
}

/// Releases the exact admission even if validation fails or its future is dropped.
pub struct RequestAdmissionGuard<'a> {
    registry: &'a RequestAdmissionRegistry,
    request_id: String,
    token: String,
}

impl Drop for RequestAdmissionGuard<'_> {
    fn drop(&mut self) {
        self.registry.finish(&self.request_id, &self.token);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn prepared_cancel_reaches_a_later_claim_and_never_polls_work() {
        let registry = RequestAdmissionRegistry::default();
        registry.prepare("id", "generation-a").unwrap();
        assert!(registry.cancel("id", "generation-a"));
        assert!(!registry.cancel("id", "generation-a"));
        assert!(matches!(
            registry.claim("id", "generation-a"),
            Err(RequestAdmissionError::Stale)
        ));
        registry.prepare("id", "generation-b").unwrap();
        let (_guard, mut cancelled) = registry.claim("id", "generation-b").unwrap();
        assert!(registry.cancel("id", "generation-b"));
        tokio::select! {
            biased;
            _ = &mut cancelled => {},
            _ = async { panic!("cancelled work was polled") } => {},
        }
    }

    #[tokio::test]
    async fn stale_cancel_cleanup_and_duplicate_claim_cannot_affect_a_replacement() {
        let registry = RequestAdmissionRegistry::default();
        registry.prepare("same", "old").unwrap();
        let (old_guard, old_cancelled) = registry.claim("same", "old").unwrap();
        registry.prepare("same", "new").unwrap();
        assert!(old_cancelled.await.is_ok());
        let (new_guard, mut new_cancelled) = registry.claim("same", "new").unwrap();
        assert!(matches!(
            registry.claim("same", "new"),
            Err(RequestAdmissionError::Stale)
        ));
        drop(old_guard);
        assert!(!registry.cancel("same", "old"));
        assert!(matches!(
            new_cancelled.try_recv(),
            Err(oneshot::error::TryRecvError::Empty)
        ));
        assert!(registry.cancel("same", "new"));
        assert!(new_cancelled.await.is_ok());
        drop(new_guard);
        assert!(!registry.cancel("same", "new"));
        registry.prepare("same", "third").unwrap();
        let (_guard, mut third) = registry.claim("same", "third").unwrap();
        assert!(!registry.cancel("same", "new"));
        assert!(matches!(
            third.try_recv(),
            Err(oneshot::error::TryRecvError::Empty)
        ));
    }

    #[test]
    fn bounded_unclaimed_admissions_expire_into_rejection_not_network_permission() {
        let registry = RequestAdmissionRegistry {
            capacity: 2,
            ttl: Duration::from_secs(1),
            ..Default::default()
        };
        let now = Instant::now();
        registry.prepare_at("a", "a", now).unwrap();
        registry.prepare_at("b", "b", now).unwrap();
        assert_eq!(
            registry.prepare_at("c", "c", now),
            Err(RequestAdmissionError::Full)
        );
        assert!(!registry.cancel("unknown", "unknown"));
        assert_eq!(registry.entries.lock().unwrap().len(), 2);
        let later = now + Duration::from_secs(2);
        registry.prepare_at("c", "c", later).unwrap();
        assert!(matches!(
            registry.claim_at("a", "a", later),
            Err(RequestAdmissionError::Stale)
        ));
        assert!(matches!(
            registry.claim_at("c", "wrong", later),
            Err(RequestAdmissionError::Stale)
        ));
        let (guard, _receiver) = registry.claim_at("c", "c", later).unwrap();
        registry
            .prepare_at("d", "d", later + Duration::from_secs(2))
            .unwrap();
        assert!(
            registry.cancel("c", "c"),
            "active operations survive reservation expiry"
        );
        drop(guard);
        assert_eq!(registry.entries.lock().unwrap().len(), 1);
        assert_eq!(
            registry.prepare("", "token"),
            Err(RequestAdmissionError::Invalid)
        );
        assert_eq!(
            registry.prepare(&"x".repeat(129), "token"),
            Err(RequestAdmissionError::Invalid)
        );
    }

    #[tokio::test]
    async fn stale_cleanup_does_not_unregister_replacement() {
        let registry = RequestCancellationRegistry::default();
        let (first_generation, first_receiver) = registry.register("same-id");
        let (_second_generation, second_receiver) = registry.register("same-id");

        assert!(first_receiver.await.is_ok());
        registry.finish("same-id", first_generation);

        assert!(registry.cancel("same-id"));
        assert!(second_receiver.await.is_ok());
    }
}

//! Pure egress-policy primitives shared by every Cognia egress filter.
//!
//! Two filters enforce host allowlists with these functions: the ADR-0028
//! per-command filtering proxy (`cognia-automation::sandbox::net_proxy`) and the
//! per-tenant sandbox egress proxy (ADR-0185). They live here, below both, so a
//! bypass fixed once is fixed everywhere. Nothing in this module does I/O.
//!
//! Beyond the allowlist matchers this module owns the one list of cloud
//! metadata endpoints that no configuration may ever except (ADR-0182), and a
//! small CIDR type for validating operator-declared internal exceptions.

use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

/// Match a single allowlist pattern against a host. Supports an exact match
/// and a leading-`*.` wildcard. `*.example.com` matches `a.example.com` and
/// `a.b.example.com` but NOT the bare `example.com` (matches srt semantics);
/// an IP literal never matches a wildcard pattern.
pub fn matches_domain_pattern(pattern: &str, host: &str) -> bool {
    let pattern = pattern.trim().to_ascii_lowercase();
    let host = host.trim().trim_end_matches('.').to_ascii_lowercase();
    if pattern.is_empty() || host.is_empty() {
        return false;
    }
    if let Some(suffix) = pattern.strip_prefix("*.") {
        if suffix.is_empty() || host.parse::<std::net::IpAddr>().is_ok() {
            return false;
        }
        return host.ends_with(&format!(".{suffix}"));
    }
    pattern == host
}

/// Validate the CONNECT authority before it is matched against the allowlist
/// or handed to the resolver. This closes the parser/resolver **differential**
/// bypass class — the bug that defeated Claude Code's network allowlist twice
/// (CVE-2025-66479 + the SOCKS5 null-byte follow-up): a host carrying an
/// embedded `\0` / CR / LF / `%` / other non-DNS byte can be matched as one
/// string by a lenient allowlist check yet resolve to a *different* target by
/// `getaddrinfo`. We accept only a syntactically valid DNS name or an IP
/// literal, so the string the allowlist sees is exactly the string the
/// resolver sees.
pub fn is_valid_hostname(host: &str) -> bool {
    // IP literals are always syntactically safe (the wildcard matcher already
    // refuses to treat them as domains).
    if host.parse::<std::net::IpAddr>().is_ok() {
        return true;
    }
    if host.is_empty() || host.len() > 253 {
        return false;
    }
    // Accept a single trailing dot (FQDN form) but require non-empty labels.
    let core = host.strip_suffix('.').unwrap_or(host);
    if core.is_empty() {
        return false;
    }
    core.split('.').all(|label| {
        let bytes = label.as_bytes();
        !bytes.is_empty()
            && bytes.len() <= 63
            && bytes
                .iter()
                .all(|b| b.is_ascii_alphanumeric() || *b == b'-')
            && bytes[0] != b'-'
            && bytes[bytes.len() - 1] != b'-'
    })
}

/// True when `host` is a syntactically valid authority AND matches any
/// allowlist pattern. The validity gate runs first so a malformed host can
/// never be allowed, regardless of allowlist contents.
pub fn is_host_allowed(host: &str, allowlist: &[String]) -> bool {
    if !is_valid_hostname(host) {
        return false;
    }
    allowlist.iter().any(|p| matches_domain_pattern(p, host))
}

/// True when an IPv4 address is in the carrier-grade-NAT shared range
/// 100.64.0.0/10 (RFC 6598) — not a public destination.
fn is_cgnat_v4(v4: &Ipv4Addr) -> bool {
    let o = v4.octets();
    o[0] == 100 && (o[1] & 0xc0) == 64
}

fn is_forbidden_v4(v4: &Ipv4Addr) -> bool {
    v4.is_loopback()
        || v4.is_private()
        || v4.is_link_local() // 169.254.0.0/16 — incl. the cloud metadata IP.
        || v4.is_unspecified()
        || v4.is_broadcast()
        || v4.is_multicast()
        || v4.is_documentation()
        || is_cgnat_v4(v4)
}

/// fc00::/7 — IPv6 unique-local addresses (the RFC 4193 private range).
fn is_ula_v6(v6: &Ipv6Addr) -> bool {
    (v6.segments()[0] & 0xfe00) == 0xfc00
}

/// fe80::/10 — IPv6 link-local addresses.
fn is_link_local_v6(v6: &Ipv6Addr) -> bool {
    (v6.segments()[0] & 0xffc0) == 0xfe80
}

/// True when `ip` is NOT a public-routable unicast destination — loopback,
/// link-local (incl. the 169.254.169.254 cloud-metadata endpoint), private /
/// ULA, unspecified, broadcast, multicast, documentation, or CGNAT. The
/// filtering proxy refuses to tunnel to any such address so an allowlisted
/// hostname that resolves (or rebinds) to an internal target cannot become an
/// SSRF primitive against the host's own network.
pub fn is_forbidden_dest_ip(ip: &IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => is_forbidden_v4(v4),
        IpAddr::V6(v6) => {
            // An IPv4-mapped IPv6 address (`::ffff:a.b.c.d`) must be judged by
            // its embedded v4 rules, or `::ffff:127.0.0.1` would slip through.
            if let Some(mapped) = v6.to_ipv4_mapped() {
                return is_forbidden_v4(&mapped);
            }
            v6.is_loopback()
                || v6.is_unspecified()
                || v6.is_multicast()
                || is_ula_v6(v6)
                || is_link_local_v6(v6)
        }
    }
}

/// How a user-configured destination may be reached (ADR-0234 §4). The
/// remote-desktop bridge dials exactly what the user confirmed, so it needs a
/// three-way answer rather than [`is_forbidden_dest_ip`]'s yes/no.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DestClass {
    /// Public unicast. Reachable after the user confirms a plaintext route.
    Public,
    /// RFC 1918, CGNAT or ULA: the user's own network, after confirmation.
    Private,
    /// Never dialed: loopback, unspecified, link-local, multicast, broadcast,
    /// documentation and every cloud metadata endpoint.
    Forbidden,
}

/// Classify one resolved address. Metadata endpoints are Forbidden even where
/// they sit inside a range that would otherwise be Private (Alibaba and
/// Volcengine inside CGNAT, AWS inside ULA). IPv4-mapped IPv6 addresses are
/// judged by their embedded IPv4 address.
pub fn classify_dest(ip: &IpAddr) -> DestClass {
    if is_metadata_ip(ip) {
        return DestClass::Forbidden;
    }
    match ip {
        IpAddr::V4(v4) => classify_v4(v4),
        IpAddr::V6(v6) => {
            if let Some(mapped) = v6.to_ipv4_mapped() {
                return classify_dest(&IpAddr::V4(mapped));
            }
            if v6.is_loopback()
                || v6.is_unspecified()
                || v6.is_multicast()
                || is_link_local_v6(v6)
            {
                DestClass::Forbidden
            } else if is_ula_v6(v6) {
                DestClass::Private
            } else {
                DestClass::Public
            }
        }
    }
}

fn classify_v4(v4: &Ipv4Addr) -> DestClass {
    if v4.is_loopback()
        || v4.is_link_local()
        || v4.is_unspecified()
        || v4.is_broadcast()
        || v4.is_multicast()
        || v4.is_documentation()
    {
        DestClass::Forbidden
    } else if v4.is_private() || is_cgnat_v4(v4) {
        DestClass::Private
    } else {
        DestClass::Public
    }
}

/// Parse a CONNECT request line — `CONNECT host:port HTTP/1.1` — into
/// `(host, port)`. Returns `None` for any other method or a malformed
/// authority.
pub fn parse_connect_target(line: &str) -> Option<(String, u16)> {
    let mut parts = line.split(' ');
    if !parts.next()?.eq_ignore_ascii_case("CONNECT") {
        return None;
    }
    let authority = parts.next()?;
    if !matches!(parts.next()?, "HTTP/1.0" | "HTTP/1.1") || parts.next().is_some() {
        return None;
    }
    parse_authority(authority, None)
}

/// Parse a strict HTTP authority, returning a bare, canonical host and port.
/// IPv6 literals require brackets; userinfo, escapes and empty/zero ports are
/// rejected so the HTTP parser, allowlist and resolver agree on the target.
pub fn parse_authority(authority: &str, default_port: Option<u16>) -> Option<(String, u16)> {
    let (host, port) = if let Some(rest) = authority.strip_prefix('[') {
        let (host, rest) = rest.split_once(']')?;
        host.parse::<Ipv6Addr>().ok()?;
        (
            host,
            if rest.is_empty() {
                None
            } else {
                Some(rest.strip_prefix(':')?)
            },
        )
    } else {
        match authority.split_once(':') {
            Some((host, port)) => (host, Some(port)),
            None => (authority, None),
        }
    };
    if !is_valid_hostname(host) {
        return None;
    }
    let port = match port {
        Some(port) if !port.is_empty() && port.bytes().all(|b| b.is_ascii_digit()) => {
            port.parse().ok()?
        }
        Some(_) => return None,
        None => default_port?,
    };
    if port == 0 {
        return None;
    }
    let host = match host.parse::<IpAddr>() {
        Ok(ip) => ip.to_string(),
        Err(_) => host.trim_end_matches('.').to_ascii_lowercase(),
    };
    Some((host, port))
}

/// Cloud instance-metadata endpoints. A route to one of these hands an
/// untrusted process the node's cloud credentials, so no egress exception — not
/// even an operator's baseline-level one — may ever cover them.
///
/// - `169.254.0.0/16`: the link-local range holding AWS/GCP/Azure/Tencent
///   (`169.254.0.23`) metadata.
/// - `100.100.100.200/32`: Alibaba Cloud ECS metadata (inside CGNAT 100.64/10).
/// - `100.96.0.96/32`: Volcengine ECS metadata (inside CGNAT 100.64/10).
/// - `fd00:ec2::254/128`: the AWS IPv6 metadata endpoint.
pub const METADATA_CIDRS: [&str; 4] = [
    "169.254.0.0/16",
    "100.100.100.200/32",
    "100.96.0.96/32",
    "fd00:ec2::254/128",
];

/// An IP network in CIDR form (`10.0.0.0/8`, `fd00::/8`, or a bare address as a
/// single-host network).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct IpCidr {
    network: IpAddr,
    prefix: u8,
}

impl IpCidr {
    /// Parse `addr/prefix` or a bare address. The network address is
    /// normalised (host bits cleared), so `10.1.2.3/8` and `10.0.0.0/8` are
    /// the same network. IPv4-mapped IPv6 input is judged as IPv4.
    pub fn parse(value: &str) -> Option<Self> {
        let value = value.trim();
        let (addr, prefix) = match value.split_once('/') {
            Some((addr, prefix)) => (addr, Some(prefix.parse::<u8>().ok()?)),
            None => (value, None),
        };
        let mut ip: IpAddr = addr.parse().ok()?;
        let mut prefix = prefix;
        if let IpAddr::V6(v6) = ip {
            if let Some(v4) = v6.to_ipv4_mapped() {
                ip = IpAddr::V4(v4);
                // `::ffff:0:0/96` is the mapped space, so a mapped prefix
                // shorter than 96 describes more than IPv4 and has no v4 form.
                prefix = Some(match prefix {
                    Some(p) => p.checked_sub(96)?,
                    None => 32,
                });
            }
        }
        let max = if ip.is_ipv4() { 32 } else { 128 };
        let prefix = prefix.unwrap_or(max);
        if prefix > max {
            return None;
        }
        Some(Self {
            network: mask(ip, prefix),
            prefix,
        })
    }

    pub fn network(&self) -> IpAddr {
        self.network
    }

    pub fn prefix(&self) -> u8 {
        self.prefix
    }

    /// Whether `ip` lies inside this network. IPv4-mapped IPv6 addresses are
    /// compared as IPv4, for the same reason [`is_forbidden_dest_ip`] does.
    pub fn contains(&self, ip: &IpAddr) -> bool {
        let ip = unmap(*ip);
        if ip.is_ipv4() != self.network.is_ipv4() {
            return false;
        }
        mask(ip, self.prefix) == self.network
    }

    /// Whether the two networks share at least one address.
    pub fn overlaps(&self, other: &IpCidr) -> bool {
        if self.network.is_ipv4() != other.network.is_ipv4() {
            return false;
        }
        let shorter = self.prefix.min(other.prefix);
        mask(self.network, shorter) == mask(other.network, shorter)
    }
}

fn unmap(ip: IpAddr) -> IpAddr {
    match ip {
        IpAddr::V6(v6) => v6.to_ipv4_mapped().map(IpAddr::V4).unwrap_or(ip),
        other => other,
    }
}

fn mask(ip: IpAddr, prefix: u8) -> IpAddr {
    match ip {
        IpAddr::V4(v4) => {
            let bits = u32::from(v4);
            let masked = if prefix == 0 {
                0
            } else {
                bits & (u32::MAX << (32 - u32::from(prefix)))
            };
            IpAddr::V4(Ipv4Addr::from(masked))
        }
        IpAddr::V6(v6) => {
            let bits = u128::from(v6);
            let masked = if prefix == 0 {
                0
            } else {
                bits & (u128::MAX << (128 - u32::from(prefix)))
            };
            IpAddr::V6(Ipv6Addr::from(masked))
        }
    }
}

/// True when `network` overlaps any cloud metadata endpoint
/// ([`METADATA_CIDRS`]). Used to refuse an egress exception before it is ever
/// stored, not merely at dial time.
pub fn overlaps_metadata(network: &IpCidr) -> bool {
    METADATA_CIDRS
        .iter()
        .filter_map(|cidr| IpCidr::parse(cidr))
        .any(|metadata| metadata.overlaps(network))
}

/// True when `ip` is a cloud metadata endpoint.
pub fn is_metadata_ip(ip: &IpAddr) -> bool {
    METADATA_CIDRS
        .iter()
        .filter_map(|cidr| IpCidr::parse(cidr))
        .any(|metadata| metadata.contains(ip))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn classify_dest_separates_lan_public_and_never_dialed() {
        let class = |s: &str| classify_dest(&s.parse::<IpAddr>().unwrap());
        for private in ["10.0.0.5", "172.16.3.4", "192.168.1.20", "100.64.0.9", "fd12::1"] {
            assert_eq!(class(private), DestClass::Private, "{private}");
        }
        for public in ["8.8.8.8", "1.1.1.1", "2606:4700::1111"] {
            assert_eq!(class(public), DestClass::Public, "{public}");
        }
        for forbidden in [
            "127.0.0.1",
            "0.0.0.0",
            "169.254.169.254",
            "169.254.1.1",
            "255.255.255.255",
            "224.0.0.1",
            "192.0.2.1",
            "::1",
            "::",
            "fe80::1",
            "ff02::1",
            "100.100.100.200",
            "100.96.0.96",
            "fd00:ec2::254",
            "::ffff:127.0.0.1",
            "::ffff:169.254.169.254",
        ] {
            assert_eq!(class(forbidden), DestClass::Forbidden, "{forbidden}");
        }
        assert_eq!(class("::ffff:192.168.1.2"), DestClass::Private);
        assert_eq!(class("::ffff:8.8.8.8"), DestClass::Public);
    }

    #[test]
    fn exact_pattern_matches_only_itself() {
        assert!(matches_domain_pattern("api.github.com", "api.github.com"));
        assert!(!matches_domain_pattern("api.github.com", "evil.com"));
        assert!(!matches_domain_pattern(
            "api.github.com",
            "x.api.github.com"
        ));
    }

    #[test]
    fn wildcard_matches_subdomains_not_the_apex() {
        assert!(matches_domain_pattern("*.example.com", "a.example.com"));
        assert!(matches_domain_pattern("*.example.com", "a.b.example.com"));
        assert!(!matches_domain_pattern("*.example.com", "example.com"));
        assert!(!matches_domain_pattern("*.example.com", "notexample.com"));
    }

    #[test]
    fn wildcard_never_matches_ip_literals() {
        assert!(!matches_domain_pattern("*.example.com", "10.0.0.1"));
        assert!(!matches_domain_pattern("*.0.0.1", "10.0.0.1"));
    }

    #[test]
    fn matching_is_case_insensitive_and_trims_trailing_dot() {
        assert!(matches_domain_pattern("API.GitHub.com", "api.github.com."));
    }

    #[test]
    fn empty_inputs_never_match() {
        assert!(!matches_domain_pattern("", "x"));
        assert!(!matches_domain_pattern("x", ""));
        assert!(!matches_domain_pattern("*.", "a.b"));
    }

    #[test]
    fn is_host_allowed_checks_every_pattern() {
        let allow = vec!["api.github.com".to_string(), "*.anthropic.com".to_string()];
        assert!(is_host_allowed("api.github.com", &allow));
        assert!(is_host_allowed("api.anthropic.com", &allow));
        assert!(!is_host_allowed("evil.com", &allow));
    }

    #[test]
    fn valid_hostname_accepts_dns_names_and_ip_literals() {
        assert!(is_valid_hostname("api.github.com"));
        assert!(is_valid_hostname("a-b.example.co.uk"));
        assert!(is_valid_hostname("example.com.")); // FQDN trailing dot
        assert!(is_valid_hostname("10.0.0.1"));
        assert!(is_valid_hostname("::1"));
    }

    #[test]
    fn valid_hostname_rejects_differential_bypass_payloads() {
        // Embedded NUL / CR / LF / percent / space / underscore — the
        // parser-vs-resolver differential class.
        assert!(!is_valid_hostname("api.github.com\u{0}.evil.com"));
        assert!(!is_valid_hostname("api.github.com\r\nHost: evil.com"));
        assert!(!is_valid_hostname("api.github.com%2e.evil.com"));
        assert!(!is_valid_hostname("bad host.com"));
        assert!(!is_valid_hostname("under_score.com"));
        assert!(!is_valid_hostname("-leadingdash.com"));
        assert!(!is_valid_hostname("trailingdash-.com"));
        assert!(!is_valid_hostname("a..b.com")); // empty label
        assert!(!is_valid_hostname(""));
        // Over-long: 64-char label / >253 total.
        assert!(!is_valid_hostname(&format!("{}.com", "a".repeat(64))));
        assert!(!is_valid_hostname(&format!("{}.com", "a.".repeat(200))));
    }

    #[test]
    fn allowlist_never_allows_a_malformed_host_even_if_it_would_pattern_match() {
        // A crafted host that string-contains an allowed name but carries a NUL
        // must be refused — the validity gate runs before pattern matching.
        let allow = vec!["api.github.com".to_string()];
        assert!(!is_host_allowed("api.github.com\u{0}", &allow));
        assert!(!is_host_allowed("api.github.com\r\n", &allow));
    }

    #[test]
    fn forbidden_dest_ip_rejects_internal_and_metadata_targets() {
        use std::str::FromStr;
        for s in [
            "127.0.0.1",        // loopback
            "10.0.0.5",         // RFC1918
            "172.16.3.4",       // RFC1918
            "192.168.1.1",      // RFC1918
            "169.254.169.254",  // cloud metadata (link-local)
            "0.0.0.0",          // unspecified
            "255.255.255.255",  // broadcast
            "100.100.0.1",      // CGNAT 100.64/10
            "::1",              // IPv6 loopback
            "fe80::1",          // IPv6 link-local
            "fc00::1",          // IPv6 ULA
            "::ffff:127.0.0.1", // IPv4-mapped loopback
            "::ffff:10.0.0.1",  // IPv4-mapped RFC1918
        ] {
            let ip = IpAddr::from_str(s).unwrap();
            assert!(is_forbidden_dest_ip(&ip), "{s} should be forbidden");
        }
    }

    #[test]
    fn forbidden_dest_ip_allows_public_targets() {
        use std::str::FromStr;
        for s in ["140.82.112.3", "1.1.1.1", "8.8.8.8", "2606:4700:4700::1111"] {
            let ip = IpAddr::from_str(s).unwrap();
            assert!(!is_forbidden_dest_ip(&ip), "{s} should be allowed");
        }
    }

    #[test]
    fn parse_connect_extracts_host_and_port() {
        assert_eq!(
            parse_connect_target("CONNECT api.github.com:443 HTTP/1.1"),
            Some(("api.github.com".to_string(), 443))
        );
        assert_eq!(
            parse_connect_target("connect example.com:80 HTTP/1.0"),
            Some(("example.com".to_string(), 80))
        );
    }

    #[test]
    fn parse_connect_rejects_non_connect_and_malformed() {
        assert_eq!(parse_connect_target("GET / HTTP/1.1"), None);
        assert_eq!(parse_connect_target("CONNECT noport HTTP/1.1"), None);
        assert_eq!(parse_connect_target("CONNECT :443 HTTP/1.1"), None);
        assert_eq!(parse_connect_target("CONNECT host:notaport HTTP/1.1"), None);
        for line in [
            "CONNECT host:443",
            "CONNECT host:443 HTTP/1.1 extra",
            "CONNECT host:0 HTTP/1.1",
            "CONNECT ::1:443 HTTP/1.1",
            "CONNECT host:+443 HTTP/1.1",
        ] {
            assert_eq!(parse_connect_target(line), None, "{line}");
        }
        assert_eq!(
            parse_connect_target("CONNECT [2606:4700:4700::1111]:443 HTTP/1.1"),
            Some(("2606:4700:4700::1111".into(), 443))
        );
    }

    #[test]
    fn http_authority_is_strict_and_normalized() {
        assert_eq!(
            parse_authority("EXAMPLE.com.:80", Some(80)),
            Some(("example.com".into(), 80))
        );
        assert_eq!(parse_authority("[::1]", Some(80)), Some(("::1".into(), 80)));
        for value in [
            "host:",
            "host:0",
            "user@host",
            "host%00",
            "host/path",
            "host:80:90",
            "[host]:80",
            " host",
            "host\r\n",
            "::1",
        ] {
            assert_eq!(parse_authority(value, Some(80)), None, "{value}");
        }
    }

    #[test]
    fn cidr_parses_and_normalises_the_network() {
        let net = IpCidr::parse("10.1.2.3/8").unwrap();
        assert_eq!(net.network(), "10.0.0.0".parse::<IpAddr>().unwrap());
        assert_eq!(net.prefix(), 8);
        assert_eq!(IpCidr::parse("10.0.0.0/8"), Some(net));
        let host = IpCidr::parse("192.0.2.7").unwrap();
        assert_eq!(host.prefix(), 32);
        assert_eq!(IpCidr::parse("fd00::/8").unwrap().prefix(), 8);
    }

    #[test]
    fn cidr_rejects_malformed_input() {
        for bad in [
            "",
            "10.0.0.0/33",
            "fd00::/129",
            "not-an-ip/8",
            "10.0.0.0/x",
            "10.0.0/8",
        ] {
            assert!(IpCidr::parse(bad).is_none(), "{bad:?} must not parse");
        }
    }

    #[test]
    fn cidr_contains_and_overlaps() {
        let net = IpCidr::parse("10.20.0.0/16").unwrap();
        assert!(net.contains(&"10.20.99.1".parse().unwrap()));
        assert!(!net.contains(&"10.21.0.1".parse().unwrap()));
        assert!(!net.contains(&"fd00::1".parse().unwrap()));
        assert!(net.overlaps(&IpCidr::parse("10.0.0.0/8").unwrap()));
        assert!(net.overlaps(&IpCidr::parse("10.20.5.0/24").unwrap()));
        assert!(!net.overlaps(&IpCidr::parse("10.21.0.0/16").unwrap()));
        assert!(!net.overlaps(&IpCidr::parse("fd00::/8").unwrap()));
    }

    #[test]
    fn ipv4_mapped_addresses_are_judged_as_ipv4() {
        let net = IpCidr::parse("100.100.100.200/32").unwrap();
        assert!(net.contains(&"::ffff:100.100.100.200".parse().unwrap()));
        assert_eq!(
            IpCidr::parse("::ffff:10.0.0.0/104"),
            IpCidr::parse("10.0.0.0/8")
        );
    }

    #[test]
    fn every_cloud_metadata_endpoint_is_recognised() {
        for ip in [
            "169.254.169.254", // AWS / GCP / Azure
            "169.254.0.23",    // Tencent Cloud
            "100.100.100.200", // Alibaba Cloud
            "100.96.0.96",     // Volcengine
            "fd00:ec2::254",   // AWS IPv6
            "::ffff:169.254.169.254",
        ] {
            assert!(
                is_metadata_ip(&ip.parse().unwrap()),
                "{ip} is a metadata endpoint"
            );
        }
        assert!(!is_metadata_ip(&"100.100.2.136".parse().unwrap()));
        assert!(!is_metadata_ip(&"8.8.8.8".parse().unwrap()));
    }

    #[test]
    fn an_exception_covering_a_metadata_endpoint_is_detected() {
        // The whole CGNAT range contains Alibaba's and Volcengine's endpoints.
        assert!(overlaps_metadata(&IpCidr::parse("100.64.0.0/10").unwrap()));
        assert!(overlaps_metadata(
            &IpCidr::parse("169.254.169.254").unwrap()
        ));
        assert!(overlaps_metadata(&IpCidr::parse("0.0.0.0/0").unwrap()));
        // A single internal mirror address next to the endpoint is fine.
        assert!(!overlaps_metadata(
            &IpCidr::parse("100.100.2.136/32").unwrap()
        ));
        assert!(!overlaps_metadata(&IpCidr::parse("10.0.0.0/8").unwrap()));
    }
}

