fn audit_all_configured_allowlist_entries_are_considered() {
    let list=ParsedAllowlist::parse(&["10.0.0.0/8".to_string(),"192.168.0.0/16".to_string()]).unwrap();
    assert!(list.contains(Ipv4Addr::new(10,1,2,3)));
    assert!(list.contains(Ipv4Addr::new(192,168,1,7)));
    assert!(!list.contains(Ipv4Addr::new(172,16,1,7)));
}

