fn audit_wrapper_matches_literal_argon2id_configuration() {
    let salt=[7_u8;16];
    let params=Params::new(19456,2,1,Some(32)).unwrap();
    let reference=Argon2::new(Algorithm::Argon2id,Version::V0x13,params);
    let mut bytes=[0_u8;32];reference.hash_password_into(b"password",&salt,&mut bytes).unwrap();
    let expected=format!("$argon2id$v=19$m=19456,t=2,p=1${}${}",STANDARD_NO_PAD.encode(salt),STANDARD_NO_PAD.encode(bytes));
