it("AUDIT: same-target writes remain queued without navigator.locks", async () => {
  const originalNavigator = Object.getOwnPropertyDescriptor(globalThis, "navigator")
  const hadNativeLock = typeof globalThis.navigator?.locks?.request === "function"
  require("node:fs").writeFileSync(".cache/test-quality-audit-20261101/round3/queue-native-lock-" + (process.env.TEST_AUDIT_PROBE_MUTATIONS === "1" ? "mutant" : "control") + ".json", JSON.stringify({ hadNativeLock }))
  Object.defineProperty(globalThis, "navigator", { configurable: true, value: {} })
  let release!: () => void
  const events: string[] = []
  const first = withBackupLock("audit-fallback", async () => {
    events.push("first")
    await new Promise<void>(resolve => { release = resolve })
    return 1
  })
  await Promise.resolve()
  const second = withBackupLock("audit-fallback", async () => { events.push("second"); return 2 })
  try {
    await withBackupLock("audit-unrelated", async () => 3)
    expect(events).toEqual(["first"])
  } finally {
    release()
    await Promise.allSettled([first, second])
    if (originalNavigator) Object.defineProperty(globalThis, "navigator", originalNavigator)
    else delete (globalThis as { navigator?: unknown }).navigator
  }
})

