      await runWebhookHandler("http://127.0.0.1:"+port+"/hook",undefined,5,"{}",outer.signal)
      assert.equal(requests,0,"cancelled hook must not issue an HTTP request")
    }finally{server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()))}
  })

#[cfg(test)]
async fn audit_chunked_origin(chunks: Vec<Vec<u8>>, content_type: &str) -> (String,tokio::task::JoinHandle<()>) {
  use tokio::io::{AsyncReadExt,AsyncWriteExt};
  let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
  let url=format!("http://{}/audit",listener.local_addr().unwrap());
  let content_type=content_type.to_string();
  let task=tokio::spawn(async move {
    let(mut socket,_)=listener.accept().await.unwrap();
    let mut request=Vec::new();let mut block=[0u8;4096];
    let header_end=loop {let n=socket.read(&mut block).await.unwrap();assert!(n>0);request.extend_from_slice(&block[..n]);if let Some(at)=request.windows(4).position(|w|w==b"\r\n\r\n"){break at+4;}};
    let headers=String::from_utf8_lossy(&request[..header_end]).to_ascii_lowercase();
    let length=headers.lines().find_map(|line|line.strip_prefix("content-length:").and_then(|n|n.trim().parse::<usize>().ok())).unwrap_or(0);
    while request.len()<header_end+length {let n=socket.read(&mut block).await.unwrap();assert!(n>0);request.extend_from_slice(&block[..n]);}
    let mut response=format!("HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n").into_bytes();
    for chunk in chunks {response.extend_from_slice(format!("{:x}\r\n",chunk.len()).as_bytes());response.extend_from_slice(&chunk);response.extend_from_slice(b"\r\n");}
    response.extend_from_slice(b"0\r\n\r\n");
    let _=socket.write_all(&response).await;let _=socket.shutdown().await;
  });
  (url,task)
}

#[tokio::test]
async fn audit_sse_rejects_an_unterminated_oversized_frame() {
  crate::proxy_config::ensure_crypto_provider();
  let(url,origin)=audit_chunked_origin(vec![vec![b'x';2*MAX_FRAME_BYTES]],"text/event-stream").await;
  let client=reqwest::Client::builder().no_proxy().build().unwrap();
  let result=tokio::time::timeout(std::time::Duration::from_secs(5),stream_sse_get(&client,&url,reqwest::header::HeaderMap::new(),&mut |_|{})).await.unwrap();
  origin.await.unwrap();
  assert!(matches!(result,Err(SseError::FrameTooLong{max})if max==MAX_FRAME_BYTES),"oversized incomplete SSE frame must be rejected: {result:?}");
}

