test("AUDIT: an EXDEV rename error actually exercises copy then delete", async (t) => {
    const fsp=(await import("node:fs/promises")).default
    const a=path.join(TMP,"audit-cross-src"),b=path.join(TMP,"audit-cross-dst")
    fs.writeFileSync(a,"cross-device-bytes")
    t.mock.method(fsp,"rename",async()=>{throw Object.assign(new Error("cross-device"),{code:"EXDEV"})})
    const result=await execFileMove({source:a,destination:b,overwrite:false})
