test("AUDIT: overwrite:false preserves a destination created after the existence check",async(t)=>{
    const fsp=(await import("node:fs/promises")).default
    const a=path.join(TMP,"audit-race-src"),b=path.join(TMP,"audit-race-dst")
    fs.writeFileSync(a,"source-bytes")
    const realCopy=fsp.copyFile.bind(fsp)
    t.mock.method(fsp,"copyFile",async(...args:Parameters<typeof fsp.copyFile>)=>{
      fs.writeFileSync(b,"concurrent-writer-bytes",{flag:"wx"})
      return realCopy(...args)
    })
    const result=await execFileCopy({source:a,destination:b,overwrite:false})
