#[tokio::test]
async fn audit_provider_pair_update_is_atomic_for_one_lock_snapshot() {
    let state=ApiKeyState::new();state.set_provider(Some("old-key".into()),Some("https://old.example".into())).await;
    let update=state.set_provider(Some("new-key".into()),Some("https://new.example".into()));
    let observe=async {let snapshot=state.inner.read().await;let pair=(snapshot.api_key.as_deref(),snapshot.base_url.as_deref());assert!(pair==(Some("old-key"),Some("https://old.example"))||pair==(Some("new-key"),Some("https://new.example")),"provider pair must not tear: {pair:?}");};
    tokio::join!(biased;update,observe);
}

